window.EXAM_STUDIES = window.EXAM_STUDIES || {}; window.EXAM_STUDIES[1] = {"1":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) הוכיחו את המשפט השני של ויירשטראס (משפט 5.37): פונקציה רציפה בקטע סגור מקבלת בו מינימום ומקסימום.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה בלי קפיצות, שמוגדרת על קטע שכולל את שני הקצוות שלו, חייבת להגיע ממש לנקודה הכי גבוהה שלה ולנקודה הכי נמוכה שלה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה בלי קפיצות, שמוגדרת על קטע שכולל את שני הקצוות שלו, חייבת להגיע ממש לנקודה הכי גבוהה שלה ולנקודה הכי נמוכה שלה.</p>\n<p><strong>תמונה בראש</strong>: נסו לדמיין שביל הליכה רציף בין שער כניסה לשער יציאה, בלי תהום ובלי קפיצות. תמיד יהיה מקום על השביל שבו נמצאים הכי גבוה, ומקום שבו נמצאים הכי נמוך. אי אפשר &quot;להתקרב לגובה שיא בלי לגעת בו לעולם&quot;, כי הגובה הזה חייב לקרות באיזו נקודה על השביל.</p>\n<p><strong>עם מספרים</strong>: על הקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> מגיעה למינימום <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> ולמקסימום <span class=\"math math-inline\" dir=\"ltr\">\\(4\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=2\\)</span>.</span></span> לעומת זאת, אם פותחים את הקצה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,2)\\)</span>,</span></span> הערכים מתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(4\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f(1.9)=3.61\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(1.99)=3.9601\\)</span>),</span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> כבר לא בקטע ולכן הפונקציה לא מקבלת מקסימום.</p>\n<p><strong>פונקציה רציפה</strong> היא פונקציה שאפשר לצייר בלי להרים את העט. <strong>קטע סגור</strong> <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> כולל את שני הקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>.</span></span> <strong>מקסימום</strong> הוא ערך שהפונקציה ממש מקבלת ושגדול או שווה לכל שאר הערכים בקטע (כמו תקרה שהגרף ממש נוגע בה), ו<strong>מינימום</strong> הוא ערך שהפונקציה ממש מקבלת ושקטן או שווה לכל השאר. <strong>חסם עליון (סופרמום)</strong> הוא התקרה הכי נמוכה מעל כל ערכי הפונקציה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>הזיזו את הסליידרים כדי לראות איך בונים סדרה של נקודות בקטע שהגבהים שלהן מתקרבים לחסם העליון, ואיך סגירות הקטע שומרת את נקודת הגבול בתוכו.</p>\n<figure class=\"demo\" id=\"demo-sup\" data-demo=\"sup\"><noscript><p>ההמחשה האינטראקטיבית דורשת JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מאיפה מגיע הגובה המועמד למקסימום","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מאיפה מגיע הגובה המועמד למקסימום</p><div class=\"callout-body\"><p>לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span> מה מבטיחה אקסיומת השלמות (משפט 3.6) על קבוצת ערכי הפונקציה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{f(x): x\\in[a,b]\\}\\)</span>?</span></p></div></div>"},{"title":"רמז 2: איך בונים סדרה ואיך מוצאים נקודה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: איך בונים סדרה ואיך מוצאים נקודה</p><div class=\"callout-body\"><p>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup\\{f(x): x\\in[a,b]\\}\\)</span>,</span> אז לפי אפיון הסופרמום (טענה 3.9) אפשר לבחור לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> שעבורה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac{1}{n}&lt;f(x_n)\\le M\\)</span>.</span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה כי היא <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> — איזה משפט מוציא ממנה תת-סדרה מתכנסת?</p></div></div>"},{"title":"רמז 3: מהמקסימום אל המינימום","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: מהמקסימום אל המינימום</p><div class=\"callout-body\"><p>לאחר שמראים <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מקבלת מקסימום בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>,</span> כדי לקבל גם מינימום בלי לחזור על כל ההוכחה מחדש, התבוננו בפונקציה ההפוכה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=-f(x)\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ראשית נראה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ולכן לקבוצת הערכים שלה יש חסם עליון סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span> נבנה סדרת נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> שעליהן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_n)\\to M\\)</span>,</span> נשתמש בבולצאנו-ויירשטראס כדי לחלץ תת-סדרה שמתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>,</span></span> ובעזרת הרציפות של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> נסיק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span> לבסוף נפעיל את התוצאה על <span class=\"math math-inline\" dir=\"ltr\">\\(-f\\)</span> כדי להראות <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מקבלת גם מינימום.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le b\\)</span>).</span> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{f(x) : x\\in[a,b]\\}\\)</span>.</span></p>\n<p><strong>שלב 1: חסימות וקיום חסם עליון סופי.</strong> לפי המשפט הראשון של ויירשטראס (משפט 5.35), כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה בקטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> היא חסומה בו. בפרט, הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסומה מלעיל. בנוסף, <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in[a,b]\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\in A\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> אינה ריקה. לפי אקסיומת השלמות (משפט 3.6), <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> קיים חסם עליון סופי, ונסמן אותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span>.</span></p>\n<p><em>למה?</em> לפני שאפשר לדבר על החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> חייבים לבדוק שני תנאים: שהקבוצה לא ריקה ושיש מעליה תקרה כלשהי. את התקרה מספק המשפט הראשון של ויירשטראס.</p>\n<p><strong>שלב 2: בניית סדרה שעליה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&gt;0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac{1}{n}&lt;M\\)</span>.</span> לפי אפיון הסופרמום (טענה 3.9), <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac{1}{n}\\)</span> אינו חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> כלומר קיים איבר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> שגדול ממנו. במילים אחרות, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M-\\frac{1}{n}&lt;f(x_n)\\le M.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{n}=0\\)</span></span> (טענה 2.10), מאריתמטיקה של גבולות (משפט 2.28) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\left(M-\\frac{1}{n}\\right)=M\\)</span>,</span> וגם הסדרה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> (טענה 2.11). לכן לפי משפט הסנדוויץ׳ (משפט 2.32):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}f(x_n)=M.\\]</div>\n<p><em>למה?</em> אם אי אפשר לגעת ישירות בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> לכל הפחות אפשר להתקרב אליו יותר ויותר: במרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1}\\)</span>,</span> במרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span>,</span> במרחק <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{3}\\)</span> וכן הלאה. כך מתקבלת סדרה של גבהים שלחוצה אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></p>\n<p><strong>שלב 3: חילוץ תת-סדרה מתכנסת שגבולה בקטע.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span>,</span> ולכן הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה (הגדרה 2.15). לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> שגבולה הוא מספר ממשי כלשהו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}x_{n_k}=c.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>,</span> ובמעבר לגבול נשמר אי-שוויון חלש (משפט 2.31), נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>\n<p><em>למה?</em> הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> חיות כולן בתוך הקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> אז הן לא יכולות לברוח לאינסוף. בולצאנו-ויירשטראס מוצא תת-סדרה שמתקבצת סביב נקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>,</span> ומכיוון ששני הקצוות שייכים לקטע, הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> לא יכולה ליפול מחוץ לקטע.</p>\n<p><strong>שלב 4: הוכחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מקבלת מקסימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> ובפרט <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span></span> (הגדרות 5.26 ו-5.16). מאפיון היינה לרציפות (טענה 5.4, המבוססת על משפט 4.30), כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\to c\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\in[a,b]\\)</span>,</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}f(x_{n_k})=f(c).\\]</div>\n<p>מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span> היא תת-סדרה של הסדרה המתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_n))\\)</span> שגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> ולכן לפי משפט 3.25 גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}f(x_{n_k})=M\\)</span>.</span> מיחידות הגבול (משפט 2.12) נסיק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span>,</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\le M=f(c)\\)</span>.</span> לפי הגדרה 5.36, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מקסימום בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>\n<p><strong>שלב 5: קיום המינימום.</strong> נגדיר פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=-f(x)\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> (מכלל הכפל בקבוע בגבולות, הנובע ממשפט 4.35 והכפלה בקבוע). ממה שכבר הוכחנו עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(d\\in[a,b]\\)</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מקבלת מקסימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-f(x)=g(x)\\le g(d)=-f(d).\\]</div>\n<p>נכפול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> ונקבל <span class=\"math math-inline\" dir=\"ltr\">\\(f(d)\\le f(x)\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מינימום בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(d\\)</span> (הגדרה 5.36).</p></div></div>","steps":["<p>תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> (עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le b\\)</span>).</span> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{f(x) : x\\in[a,b]\\}\\)</span>.</span></p>\n<p><strong>שלב 1: חסימות וקיום חסם עליון סופי.</strong> לפי המשפט הראשון של ויירשטראס (משפט 5.35), כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה בקטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> היא חסומה בו. בפרט, הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסומה מלעיל. בנוסף, <span class=\"math math-inline\" dir=\"ltr\">\\(a\\in[a,b]\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(a)\\in A\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> אינה ריקה. לפי אקסיומת השלמות (משפט 3.6), <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> קיים חסם עליון סופי, ונסמן אותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span>.</span></p>\n<p><em>למה?</em> לפני שאפשר לדבר על החסם העליון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> חייבים לבדוק שני תנאים: שהקבוצה לא ריקה ושיש מעליה תקרה כלשהי. את התקרה מספק המשפט הראשון של ויירשטראס.</p>","<p><strong>שלב 2: בניית סדרה שעליה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&gt;0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac{1}{n}&lt;M\\)</span>.</span> לפי אפיון הסופרמום (טענה 3.9), <span class=\"math math-inline\" dir=\"ltr\">\\(M-\\frac{1}{n}\\)</span> אינו חסם מלעיל של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span>,</span> כלומר קיים איבר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> שגדול ממנו. במילים אחרות, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\in[a,b]\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[M-\\frac{1}{n}&lt;f(x_n)\\le M.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{n}=0\\)</span></span> (טענה 2.10), מאריתמטיקה של גבולות (משפט 2.28) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\left(M-\\frac{1}{n}\\right)=M\\)</span>,</span> וגם הסדרה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span></span> (טענה 2.11). לכן לפי משפט הסנדוויץ׳ (משפט 2.32):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}f(x_n)=M.\\]</div>\n<p><em>למה?</em> אם אי אפשר לגעת ישירות בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> לכל הפחות אפשר להתקרב אליו יותר ויותר: במרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1}\\)</span>,</span> במרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span>,</span> במרחק <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{3}\\)</span> וכן הלאה. כך מתקבלת סדרה של גבהים שלחוצה אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>.</span></p>","<p><strong>שלב 3: חילוץ תת-סדרה מתכנסת שגבולה בקטע.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span>,</span> ולכן הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה (הגדרה 2.15). לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> שגבולה הוא מספר ממשי כלשהו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}x_{n_k}=c.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>,</span> ובמעבר לגבול נשמר אי-שוויון חלש (משפט 2.31), נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>\n<p><em>למה?</em> הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> חיות כולן בתוך הקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> אז הן לא יכולות לברוח לאינסוף. בולצאנו-ויירשטראס מוצא תת-סדרה שמתקבצת סביב נקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>,</span> ומכיוון ששני הקצוות שייכים לקטע, הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> לא יכולה ליפול מחוץ לקטע.</p>","<p><strong>שלב 4: הוכחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> מקבלת מקסימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> ובפרט <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span></span> (הגדרות 5.26 ו-5.16). מאפיון היינה לרציפות (טענה 5.4, המבוססת על משפט 4.30), כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\to c\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\in[a,b]\\)</span>,</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}f(x_{n_k})=f(c).\\]</div>\n<p>מצד שני, <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_{n_k}))\\)</span> היא תת-סדרה של הסדרה המתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((f(x_n))\\)</span> שגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span>,</span> ולכן לפי משפט 3.25 גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}f(x_{n_k})=M\\)</span>.</span> מיחידות הגבול (משפט 2.12) נסיק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(c)=M\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\sup A\\)</span>,</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\le M=f(c)\\)</span>.</span> לפי הגדרה 5.36, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מקסימום בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> בנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>","<p><strong>שלב 5: קיום המינימום.</strong> נגדיר פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=-f(x)\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> (מכלל הכפל בקבוע בגבולות, הנובע ממשפט 4.35 והכפלה בקבוע). ממה שכבר הוכחנו עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(d\\in[a,b]\\)</span> שבה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מקבלת מקסימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-f(x)=g(x)\\le g(d)=-f(d).\\]</div>\n<p>נכפול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> ונקבל <span class=\"math math-inline\" dir=\"ltr\">\\(f(d)\\le f(x)\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[a,b]\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מקבלת מינימום בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> בנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(d\\)</span> (הגדרה 5.36).</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>בשאלה הזו בניגוד למבחנים אחרים <strong>לא</strong> כתוב &quot;מספיק להוכיח את קיום המקסימום&quot; — לכן אסור לוותר על ההוכחה למינימום (דרך <span class=\"math math-inline\" dir=\"ltr\">\\(g=-f\\)</span> או סימטרית עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf\\)</span>).</span></li><li>לשכוח לציין <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span></span> אינה ריקה לפני שמפעילים את אקסיומת השלמות (משפט 3.6).</li><li>להחליף בין הסופרמום לבין ההנחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> חסומה: הסופרמום קיים <em>בגלל</em> המשפט הראשון של ויירשטראס (5.35).</li><li>לשכוח להראות בעזרת משפט 2.31 שהגבול <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> אכן שייך לקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> — בלי הסגירות אי אפשר להפעיל שם את הרציפות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>.</span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/31/q1\">2024א · מועד 96, שאלה 1</a> · <a href=\"#/exams/33/q1\">2025א · מועד 81, שאלה 1</a></p>","mc":null},"2":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) <strong>א.</strong> (10 נק׳) הוכיחו את משפט 2.43 ה: אם <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{a_n}=0\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}e^{-\\frac{1}{x^2}} &amp; x\\ne 0\\\\ 0 &amp; x=0\\end{cases}\\)</span>.</span> הוכיחו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>.</span></span> הקפידו לנמק כל שלב בחישובים.</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשמחלקים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> במספרים שהולכים וגדלים בלי סוף, התוצאות הולכות ומתקרבות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשמחלקים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> במספרים שהולכים וגדלים בלי סוף, התוצאות הולכות ומתקרבות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: תחשבו על פיצה אחת שמתחלקת בין קבוצה שהולכת וגדלה: <span class=\"math math-inline\" dir=\"ltr\">\\(10\\)</span> אנשים, <span class=\"math math-inline\" dir=\"ltr\">\\(1000\\)</span> אנשים, מיליון אנשים. ככל שיש יותר אנשים (איברי הסדרה גדלים מעל כל גובה שנקבע), החתיכה של כל אדם <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span>)</span> נהיית דקה יותר וקרובה יותר <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: אם ניקח סדרה כמו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2n\\)</span> ששואפת לאינסוף ונרצה שהמרחק של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> יהיה קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.01\\)</span>,</span></span> נבקש <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> יעבור את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{0.01}=100\\)</span>.</span> החל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(n=51\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge 102&gt;100\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{a_n}\\le\\frac{1}{102}&lt;0.01\\)</span>.</span></p>\n<p><strong>שאיפה לאינסוף <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim a_n=\\infty\\)</span>)</span></strong> פירושה שלכל תקרה <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> שנבחר, הסדרה עוברת את <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> החל ממקום מסוים ונשארת מעליה. <strong>שאיפה לאפס</strong> פירושה שלכל רדיוס <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> (שגיאה מותרת סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span> החל ממקום מסוים הסדרה נכנסת לתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((-\\varepsilon,\\varepsilon)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=0.5n\\)</span> (כעקומה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.5x\\)</span>)</span> ובאדום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}=\\frac{2}{x}\\)</span>.</span> הסליידר <span class=\"math math-inline\" dir=\"ltr\">\\(r\\)</span> מייצג את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>:</span> הקו המקווקו הסגול הוא התקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{r}\\)</span>,</span> והירוק הוא הגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\)</span>.</span> ברגע שעוברים את <span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac{2}{r}\\)</span> (קו אפור), הכחול מעל <span class=\"math math-inline\" dir=\"ltr\">\\(M\\)</span> ולכן האדום יורד מתחת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0,&quot;xmax&quot;:14,&quot;ymin&quot;:-0.5,&quot;ymax&quot;:11}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;r=0.25&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.1,&quot;max&quot;:0.8,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=0.5x&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{1}{0.5x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;Mline&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=\\\\frac{1}{r}&quot;,&quot;color&quot;:&quot;#6042a6&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;epsline&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=r&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;Nline&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=\\\\frac{2}{r}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pM&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(\\\\frac{2}{r},\\\\frac{1}{r})&quot;,&quot;color&quot;:&quot;#6042a6&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;peps&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(\\\\frac{2}{r},r)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מתרגמים מה שצריך להוכיח","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מתרגמים מה שצריך להוכיח</p><div class=\"callout-body\"><p>כדי להוכיח לפי ההגדרה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{a_n}=0\\)</span>,</span></span> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> צריך למצוא <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> כך שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{1}{a_n}-0\\right|&lt;\\varepsilon\\)</span>.</span></p></div></div>"},{"title":"רמז 2: מתי $\\frac{1}{a_n}$ קטן מ-$\\varepsilon$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מתי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span></p><div class=\"callout-body\"><p>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span>,</span> האי-שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}&lt;\\varepsilon\\)</span> שקול לכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;\\frac{1}{\\varepsilon}\\)</span></span> (טענה 1.42).</p></div></div>"},{"title":"רמז 3: מה לגבי ההגדרה ואיברים ראשונים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: מה לגבי ההגדרה ואיברים ראשונים</p><div class=\"callout-body\"><p>הפעילו את הגדרת הגבול האינסופי (הגדרה 2.36) על הנתון <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span> עם הבחירה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{\\varepsilon}\\)</span>,</span> ושימו לב שמקבלים גם <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span></span> כמעט תמיד (ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> מוגדר היטב החל <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span>).</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> שרירותי, נציב <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{\\varepsilon}&gt;0\\)</span> בהגדרת הגבול האינסופי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>,</span> ונקבל <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> שממנו והלאה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;\\frac{1}{\\varepsilon}&gt;0\\)</span>.</span> מכאן לפי היפוך אי-שוויון נקבל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span></span> מוגדר ומקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{a_n}&lt;\\varepsilon\\)</span>,</span> וזה בדיוק גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: קביעת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> והפעלת הגדרת הגבול האינסופי.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{\\varepsilon}\\)</span> (מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>).</span> כיוון שנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span>,</span> לפי הגדרת הגבול האינסופי (הגדרה 2.36) עבור <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{\\varepsilon}\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n&gt;M=\\frac{1}{\\varepsilon}.\\]</div>\n<p><em>למה?</em> אם נרצה שהשבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> יהיה קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>,</span></span> המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> חייב להיות גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\varepsilon}\\)</span>.</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> שואפת לאינסוף, היא תמיד עוברת בסוף כל מספר שנזרוק עליה, ובפרט את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\varepsilon}\\)</span>.</span></p>\n<p><strong>שלב 2: טיפול בהגדרה ובהיפוך האי-שוויון.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;\\frac{1}{\\varepsilon}&gt;0\\)</span>.</span> בפרט <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ne 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> ולכן הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> מוגדרת כמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> (איברים בודדים בהתחלה שבהם אולי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=0\\)</span> אינם משנים את הגבול, משפט 2.17). כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\varepsilon}&gt;0\\)</span>,</span></span> היפוך אי-שוויון (טענה 1.42) נותן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;\\frac{1}{a_n}&lt;\\varepsilon.\\]</div>\n<p><strong>שלב 3: הסקת הגבול.</strong> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{1}{a_n}-0\\right|=\\frac{1}{a_n}&lt;\\varepsilon\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>.</span> לפי הגדרת גבול של סדרה (הגדרה 2.9), הוכחנו כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{a_n}=0\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: קביעת <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> והפעלת הגדרת הגבול האינסופי.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{\\varepsilon}\\)</span> (מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span>).</span> כיוון שנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span>,</span> לפי הגדרת הגבול האינסופי (הגדרה 2.36) עבור <span class=\"math math-inline\" dir=\"ltr\">\\(M=\\frac{1}{\\varepsilon}\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n&gt;M=\\frac{1}{\\varepsilon}.\\]</div>\n<p><em>למה?</em> אם נרצה שהשבר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> יהיה קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>,</span></span> המכנה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> חייב להיות גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\varepsilon}\\)</span>.</span></span> מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> שואפת לאינסוף, היא תמיד עוברת בסוף כל מספר שנזרוק עליה, ובפרט את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\varepsilon}\\)</span>.</span></p>","<p><strong>שלב 2: טיפול בהגדרה ובהיפוך האי-שוויון.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;\\frac{1}{\\varepsilon}&gt;0\\)</span>.</span> בפרט <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ne 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> ולכן הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}\\)</span> מוגדרת כמעט לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> (איברים בודדים בהתחלה שבהם אולי <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=0\\)</span> אינם משנים את הגבול, משפט 2.17). כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\varepsilon}&gt;0\\)</span>,</span></span> היפוך אי-שוויון (טענה 1.42) נותן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;\\frac{1}{a_n}&lt;\\varepsilon.\\]</div>","<p><strong>שלב 3: הסקת הגבול.</strong> מאחר <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\left|\\frac{1}{a_n}-0\\right|=\\frac{1}{a_n}&lt;\\varepsilon\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>.</span> לפי הגדרת גבול של סדרה (הגדרה 2.9), הוכחנו כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{a_n}=0\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח לציין <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ne 0\\)</span> החל ממקום מסוים (כי ייתכן שבאחד האיברים הראשונים <span class=\"math math-inline\" dir=\"ltr\">\\(a_1=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_1}\\)</span></span> כלל אינו מוגדר; בגבול סדרות מספיק שהביטוי מוגדר כמעט לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>).</span></li><li>לכתוב <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{a_n}&lt;\\varepsilon\\)</span> ולהפוך בלי לבדוק סימן — היפוך אי-שוויון דורש חיוביות של שני הצדדים.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הפונקציה הזו משתטחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> סביב <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> כל כך מהר, שגם השיפוע שלה נעלם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בצורה חלקה ובלי קפיצות.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הפונקציה הזו משתטחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> סביב <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> כל כך מהר, שגם השיפוע שלה נעלם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בצורה חלקה ובלי קפיצות.</p>\n<p><strong>תמונה בראש</strong>: דמיינו כביש שעולה משמאל ומימין כמו שתי גבעות, אבל כשמתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הוא נהיה שטוח לגמרי כמו רצפה. לא רק שאין בו פינה חדה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (השיפוע שם הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span> אלא שאם נוסעים לאורך הכביש ומודדים את השיפוע בכל נקודה, מד השיפוע עצמו יורד <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בלי קפיצה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: כשמתקרבים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x^2}\\)</span> צונח במהירות מסחררת: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> הערך הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1}\\approx 0.368\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.5\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{-4}\\approx 0.018\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.2\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^{-25}\\approx 1.4\\cdot 10^{-11}\\)</span>.</span> אפילו אם מחלקים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> או <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\)</span></span> (כמו שקורה בנגזרת), הביטוי עדיין שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>פונקציה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></strong> פירושה שבכל נקודה ממשית יש לפונקציה שיפוע מוגדר וסופי (נגזרת). <strong><span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></strong> פירושה שפונקציית השיפועים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> לא קופצת בשום נקודה — וגם בנקודת התפר <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)\\)</span>.</span></span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הגרף של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-1/x^2}\\)</span> (<span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>),</span></span> ובכתום הנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2}{x^3}e^{-1/x^2}\\)</span> (<span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>).</span></span> הזיזו את הסליידר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span>:</span> ככל שמתקרבים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> גם <span class=\"math math-inline\" dir=\"ltr\">\\(f(t)\\)</span> וגם השיפוע <span class=\"math math-inline\" dir=\"ltr\">\\(f'(t)\\)</span> נהיים שטוחים ומתכנסים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-2.5,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-1.3,&quot;ymax&quot;:1.3}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=0.8&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-2,&quot;max&quot;:2,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=e^{-\\\\frac{1}{x^{2}}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{2}{x^{3}}e^{-\\\\frac{1}{x^{2}}}&quot;,&quot;color&quot;:&quot;#fa7e19&quot;},{&quot;id&quot;:&quot;z&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;ptf&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;ptg&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,g(t))&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מפצלים לשני אזורים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מפצלים לשני אזורים</p><div class=\"callout-body\"><p><span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span></span> הפונקציה נתונה בנוסחה אחת ואפשר להשתמש בכללי הגזירה. <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הנוסחה מתפצלת, ולכן חייבים לחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)\\)</span> ישירות מהגדרת הנגזרת (הגדרה 7.7).</p></div></div>"},{"title":"רמז 2: איך מחשבים את הגבול ב-$x\\to 0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: איך מחשבים את הגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span></span></p><div class=\"callout-body\"><p>בשני המקומות (גם בגזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> וגם ברציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span></span> צריך לחשב גבולות מהצורה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-1/x^2}}{x}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{2e^{-1/x^2}}{x^3}\\)</span></span> <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>.</span></span> אפשר לחסום <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> מלמטה בעזרת <span class=\"math math-inline\" dir=\"ltr\">\\(e^u&gt;1+u&gt;u\\)</span> (מלגראנז׳) ולהשתמש בסנדוויץ׳, או לפצל לימין ולשמאל ולהציב <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\)</span> עם לופיטל.</p></div></div>"},{"title":"רמז 3: מה צריך כדי ש-$f'$ תהיה רציפה ב-$\\mathbb R$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: מה צריך כדי <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> תהיה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span></p><div class=\"callout-body\"><p>אחרי שיודעים <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> מוגדרת בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (כולל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>),</span></span> בודקים רציפות של <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> (אריתמטיקה והרכבה של רציפות) ועבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> בודקים <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f'(x)=f'(0)\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> נגזור לפי כלל השרשרת ונקבל נוסחה של <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> שגם ברור ממנה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>.</span> לאחר מכן נוכיח בעזרת משפט לגראנז׳ <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^u&gt;u\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span>,</span> וממנו נגזור חסם חזק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;e^{-1/x^2}&lt;4x^4\\)</span>.</span> חסם זה יוכיח באמצעות כלל הסנדוויץ׳ הן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span></span> (לפי ההגדרה) והן <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f'(x)=0=f'(0)\\)</span></span> (רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: גזירות ורציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>.</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>,</span> קיימת סביבה פתוחה של <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> שאינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> ובה מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-\\frac{1}{x^2}}\\)</span>.</span></p>\n<ul><li>הפונקציה הפנימית <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=-\\frac{1}{x^2}\\)</span> גזירה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> (כמנה של פונקציה קבועה בפונקציה גזירה שאינה מתאפסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>,</span> משפטים 7.16 ו-7.18), ונגזרתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=-\\frac{-2x}{x^4}=\\frac{2}{x^3}\\)</span>.</span></li><li>הפונקציה החיצונית <span class=\"math math-inline\" dir=\"ltr\">\\(u\\mapsto e^u\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ונגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> (משפט 7.30).</li></ul>\n<p>לפי כלל השרשרת (משפט 7.21), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=e^{-\\frac{1}{x^2}}\\cdot\\frac{2}{x^3}=\\frac{2e^{-\\frac{1}{x^2}}}{x^3}.\\]</div>\n<p>כמו כן, בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> היא מנה והרכבה של פונקציות רציפות שבהן המכנה אינו מתאפס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\ne 0\\)</span>,</span> פולינומים רציפים <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span></span> רציפה לפי משפט 6.14, יחד עם הרכבת רציפות משפט 5.15 ואריתמטיקת גבולות משפט 4.35). לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>.</span></p>\n<p><strong>שלב 2: אי-שוויון עזר להתנהגות ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></strong> נוכיח תחילה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^u&gt;u\\)</span>:</span> נתבונן בפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\varphi(t)=e^t\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,u]\\)</span>.</span> היא גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 7.30) ולכן רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,u]\\)</span></span> (משפט 7.9) וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,u)\\)</span>.</span></span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,u)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{e^u-e^0}{u-0}=\\varphi'(c)=e^c.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> עולה ממש, מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^c&gt;e^0=1\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span>,</span></span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^u-1&gt;u \\implies e^u&gt;1+u&gt;u.\\]</div>\n<p><em>למה?</em> משפט לגראנז׳ נותן דרך קצרה ומנומקת לגמרי להראות <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span></span> גדל מהר יותר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(u\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span>,</span> בלי להסתמך על טורי טיילור.</p>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=\\frac{1}{2x^2}&gt;0\\)</span>,</span> ולכן מהאי-שוויון שהוכחנו:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^{\\frac{1}{2x^2}}&gt;\\frac{1}{2x^2}&gt;0.\\]</div>\n<p>נעלה את שני האגפים החיוביים בריבוע (שומר על אי-השוויון):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^{\\frac{1}{x^2}}=\\left(e^{\\frac{1}{2x^2}}\\right)^2&gt;\\frac{1}{4x^4}&gt;0.\\]</div>\n<p>נהפוך את שני האגפים החיוביים (הופך את כיוון אי-השוויון, טענה 1.42) ונקבל לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;e^{-\\frac{1}{x^2}}&lt;4x^4.\\]</div>\n<p><strong>שלב 3: גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> לפי הגדרה 7.7.</strong> נבדוק אם קיים גבול סופי למנת ההפרשים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}=\\lim_{x\\to 0}\\frac{e^{-\\frac{1}{x^2}}-0}{x}=\\lim_{x\\to 0}\\frac{e^{-\\frac{1}{x^2}}}{x}.\\]</div>\n<p>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> לפי החסם משלב 2 מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{e^{-\\frac{1}{x^2}}}{x}\\right|=\\frac{e^{-\\frac{1}{x^2}}}{|x|}&lt;\\frac{4x^4}{|x|}=4|x|^3,\\]</div>\n<p>כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-4|x|^3&lt;\\frac{e^{-\\frac{1}{x^2}}}{x}&lt;4|x|^3.\\]</div>\n<p>כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}(-4|x|^3)=\\lim_{x\\to 0}(4|x|^3)=0\\)</span> (מגבול <span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\to 0\\)</span> ואריתמטיקת גבולות, משפט 4.35). לפי כלל הסנדוויץ׳ לפונקציות (משפט 4.43) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}=0.\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span> יחד עם שלב 1, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></p>\n<p><em>למה?</em> במקום לופיטל שלוש פעמים והצבת <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\)</span> שדורשת פיצול <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span>,</span></span> החסם <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x^2}&lt;4x^4\\)</span> מדגים ישר למה האקספוננט מנצח כל חזקה של <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> משני הצדדים בבת אחת.</p>\n<p><strong>שלב 4: רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></strong> לאחר שמצאנו את <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> מתקיים לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2e^{-1/x^2}}{x^3}\\)</span></span> ובנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span> נבדוק לפי הגדרה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f'(x)=f'(0)\\)</span>:</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> משלב 2 מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)|=\\frac{2e^{-\\frac{1}{x^2}}}{|x|^3}&lt;\\frac{2\\cdot 4x^4}{|x|^3}=8|x|,\\]</div>\n<p>כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-8|x|&lt;f'(x)&lt;8|x|.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}(-8|x|)=\\lim_{x\\to 0}(8|x|)=0\\)</span>,</span></span> לפי כלל הסנדוויץ׳ לפונקציות (משפט 4.43) מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}f'(x)=0=f'(0).\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ויחד עם שלב 1 נובע כי <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: גזירות ורציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>.</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\ne 0\\)</span>,</span> קיימת סביבה פתוחה של <span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span> שאינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> ובה מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=e^{-\\frac{1}{x^2}}\\)</span>.</span></p>\n<ul><li>הפונקציה הפנימית <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=-\\frac{1}{x^2}\\)</span> גזירה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> (כמנה של פונקציה קבועה בפונקציה גזירה שאינה מתאפסת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>,</span> משפטים 7.16 ו-7.18), ונגזרתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(h'(x)=-\\frac{-2x}{x^4}=\\frac{2}{x^3}\\)</span>.</span></li><li>הפונקציה החיצונית <span class=\"math math-inline\" dir=\"ltr\">\\(u\\mapsto e^u\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> ונגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span> (משפט 7.30).</li></ul>\n<p>לפי כלל השרשרת (משפט 7.21), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=e^{-\\frac{1}{x^2}}\\cdot\\frac{2}{x^3}=\\frac{2e^{-\\frac{1}{x^2}}}{x^3}.\\]</div>\n<p>כמו כן, בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> היא מנה והרכבה של פונקציות רציפות שבהן המכנה אינו מתאפס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^3\\ne 0\\)</span>,</span> פולינומים רציפים <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span></span> רציפה לפי משפט 6.14, יחד עם הרכבת רציפות משפט 5.15 ואריתמטיקת גבולות משפט 4.35). לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>.</span></p>","<p><strong>שלב 2: אי-שוויון עזר להתנהגות ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></strong> נוכיח תחילה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^u&gt;u\\)</span>:</span> נתבונן בפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\varphi(t)=e^t\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,u]\\)</span>.</span> היא גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 7.30) ולכן רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,u]\\)</span></span> (משפט 7.9) וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,u)\\)</span>.</span></span> לפי משפט לגראנז׳ (משפט 8.6), קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,u)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{e^u-e^0}{u-0}=\\varphi'(c)=e^c.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span></span> והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(e^t\\)</span> עולה ממש, מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^c&gt;e^0=1\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span>,</span></span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^u-1&gt;u \\implies e^u&gt;1+u&gt;u.\\]</div>\n<p><em>למה?</em> משפט לגראנז׳ נותן דרך קצרה ומנומקת לגמרי להראות <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^u\\)</span></span> גדל מהר יותר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(u\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u&gt;0\\)</span>,</span> בלי להסתמך על טורי טיילור.</p>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(u=\\frac{1}{2x^2}&gt;0\\)</span>,</span> ולכן מהאי-שוויון שהוכחנו:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^{\\frac{1}{2x^2}}&gt;\\frac{1}{2x^2}&gt;0.\\]</div>\n<p>נעלה את שני האגפים החיוביים בריבוע (שומר על אי-השוויון):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[e^{\\frac{1}{x^2}}=\\left(e^{\\frac{1}{2x^2}}\\right)^2&gt;\\frac{1}{4x^4}&gt;0.\\]</div>\n<p>נהפוך את שני האגפים החיוביים (הופך את כיוון אי-השוויון, טענה 1.42) ונקבל לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0&lt;e^{-\\frac{1}{x^2}}&lt;4x^4.\\]</div>","<p><strong>שלב 3: גזירות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> לפי הגדרה 7.7.</strong> נבדוק אם קיים גבול סופי למנת ההפרשים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}=\\lim_{x\\to 0}\\frac{e^{-\\frac{1}{x^2}}-0}{x}=\\lim_{x\\to 0}\\frac{e^{-\\frac{1}{x^2}}}{x}.\\]</div>\n<p>לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> לפי החסם משלב 2 מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left|\\frac{e^{-\\frac{1}{x^2}}}{x}\\right|=\\frac{e^{-\\frac{1}{x^2}}}{|x|}&lt;\\frac{4x^4}{|x|}=4|x|^3,\\]</div>\n<p>כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-4|x|^3&lt;\\frac{e^{-\\frac{1}{x^2}}}{x}&lt;4|x|^3.\\]</div>\n<p>כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}(-4|x|^3)=\\lim_{x\\to 0}(4|x|^3)=0\\)</span> (מגבול <span class=\"math math-inline\" dir=\"ltr\">\\(|x|\\to 0\\)</span> ואריתמטיקת גבולות, משפט 4.35). לפי כלל הסנדוויץ׳ לפונקציות (משפט 4.43) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}\\frac{f(x)-f(0)}{x-0}=0.\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> ומתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span> יחד עם שלב 1, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></p>\n<p><em>למה?</em> במקום לופיטל שלוש פעמים והצבת <span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\)</span> שדורשת פיצול <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^+\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0^-\\)</span>,</span></span> החסם <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x^2}&lt;4x^4\\)</span> מדגים ישר למה האקספוננט מנצח כל חזקה של <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> משני הצדדים בבת אחת.</p>","<p><strong>שלב 4: רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></strong> לאחר שמצאנו את <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> מתקיים לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{2e^{-1/x^2}}{x^3}\\)</span></span> ובנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span>.</span> נבדוק לפי הגדרה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f'(x)=f'(0)\\)</span>:</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> משלב 2 מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)|=\\frac{2e^{-\\frac{1}{x^2}}}{|x|^3}&lt;\\frac{2\\cdot 4x^4}{|x|^3}=8|x|,\\]</div>\n<p>כלומר לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-8|x|&lt;f'(x)&lt;8|x|.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}(-8|x|)=\\lim_{x\\to 0}(8|x|)=0\\)</span>,</span></span> לפי כלל הסנדוויץ׳ לפונקציות (משפט 4.43) מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}f'(x)=0=f'(0).\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span></span> ויחד עם שלב 1 נובע כי <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f'(x)\\)</span> ולהסיק מכך ישירות <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)=0\\)</span></span> בלי לחשב את <span class=\"math math-inline\" dir=\"ltr\">\\(f'(0)\\)</span> מהגדרה — אסור! יש פונקציות שבהן גבול הנגזרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כלל אינו נותן קיום נגזרת בלי רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (כגון קפיצה בערך <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span></span></li><li>לנסות להפעיל את כלל לופיטל על <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-1/x^2}}{x}\\)</span> במעבר אחד בלי להחליף משתנה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t=\\frac{1}{x}\\)</span>:</span></span> גזירה ישירה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-1/x^2}}{x}\\)</span> רק מסבכת את החזקות של <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> במכנה.</li><li>להשתמש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(e^{-1/x^2}\\to 0\\)</span></span> לבד כדי להסיק <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e^{-1/x^2}}{x^3}\\to 0\\)</span> — זו צורה בלתי מוגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{0}\\)</span> ודרוש חישוב מפורש ומנומק.</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"3":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>.</span></span> <strong>א.</strong> הוכיחו שאם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>,</span></span> אז לכל שתי סדרות <span class=\"math math-inline\" dir=\"ltr\">\\((x_n),(y_n)\\)</span> המקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0\\)</span>.</span></p>\n<p><strong>ב.</strong> הוכיחו שאם לכל שתי סדרות <span class=\"math math-inline\" dir=\"ltr\">\\((x_n),(y_n)\\)</span> המקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0\\)</span>,</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb{R}\\)</span>.</span></span> רמז: הוכחת משפט קנטור.</p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">בפונקציה שמוגבלת בקצב השינוי שלה בכל הארץ, אם שני זוגות של קלטים מתקרבים זה לזה לאפס, גם הפלטים שלהם מתקרבים זה לזה לאפס.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: בפונקציה שמוגבלת בקצב השינוי שלה בכל הארץ, אם שני זוגות של קלטים מתקרבים זה לזה לאפס, גם הפלטים שלהם מתקרבים זה לזה לאפס.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על שביל שכולו בעלייה מתונה: אין בו צוקים בשום מקום, גם לא באופק הרחוק. אם שתי מטיילות הולכות לאורך השביל והמרחק האופקי ביניהן הולך וקטן <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> אז גם ההבדל בגובה ביניהן הולך וקטן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> — לא משנה לאן בישר הממשי הן מטיילות.</p>\n<p><strong>עם מספרים</strong>: בפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin x\\)</span> (שרציפה במ&quot;ש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>),</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(x_n=n\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_n=n+\\frac{1}{n}\\)</span>,</span></span> המרחק האופקי הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\to 0\\)</span>,</span> והפרש הגבהים <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin(n+\\frac{1}{n})-\\sin n|\\)</span> קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span></span> (לפי לגראנז׳) ולכן גם הוא שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> אף <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\to\\infty\\)</span>.</span></span></p>\n<p><strong>רציפות במידה שווה (במ&quot;ש)</strong> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> פירושה שלכל מרחק אנכי שנרצה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>),</span> קיים מרחק אופקי קבוע <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span>)</span> שמבטיח שבכל מקום על ציר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span> שתי נקודות במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> יתנו פלטים במרחק קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול פונקציה שרציפה במידה שווה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=0.5x+0.4\\sin(2x)\\)</span>.</span> הזיזו את הסליידר <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> (המיקום של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span>)</span> ואת <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> (המרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n\\)</span>):</span> לא משנה כמה רחוק מזיזים את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span>,</span> כשמקטינים את <span class=\"math math-inline\" dir=\"ltr\">\\(h\\)</span> הפער בגבהים של הנקודות הכחולה והאדומה נהיה קטן בכל מקום.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-4,&quot;xmax&quot;:5,&quot;ymin&quot;:-3,&quot;ymax&quot;:3.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=1.2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:-3,&quot;max&quot;:3.5,&quot;step&quot;:0.2}},{&quot;id&quot;:&quot;h&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;h=0.25&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:0.8,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=0.5x+0.4\\\\sin(2x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;px&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;py&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t+h,f(t+h))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;lx&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=t&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;ly&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=t+h&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קישור בין שתי ההגדרות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קישור בין שתי ההגדרות</p><div class=\"callout-body\"><p>רשמו תחילה מה אומרת הגדרה 5.46 על <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>:</span> איזה מספר קיים?</p></div></div>"},{"title":"רמז 2: שימוש בגבול $y_n-x_n\\to 0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש בגבול <span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n\\to 0\\)</span></p><div class=\"callout-body\"><p>ברגע שקיבלנו <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> מרציפות במ&quot;ש, היעזרו בהגדרת הגבול של הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((y_n-x_n)\\)</span> עבור האתגר <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כדי להבטיח <span class=\"math math-inline\" dir=\"ltr\">\\(|y_n-x_n|&lt;\\delta\\)</span> החל מאינדקס <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span>.</span></p></div></div>"},{"title":"רמז 3: סגירת ה-$\\varepsilon$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: סגירת <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span></p><div class=\"callout-body\"><p>מאותו <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> והלאה, מיקום <span class=\"math math-inline\" dir=\"ltr\">\\(y_n,x_n\\)</span> קרובים מספיק כדי שרציפות במ&quot;ש תסיק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|&lt;\\varepsilon\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ניקח שתי סדרות עם <span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n\\to 0\\)</span> ונרצה להראות לפי ההגדרה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y_n)-f(x_n)\\to 0\\)</span>.</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> נשלוף את <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span></span> מהרציפות במידה שווה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>,</span> ואז מהתכנסות <span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n\\to 0\\)</span> נקבל <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|y_n-x_n|&lt;\\delta\\)</span>,</span> מה שמכריח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|&lt;\\varepsilon\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p>תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n),(y_n)\\)</span> סדרות ממשיות המקיימות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span>.</span> נרצה להוכיח לפי הגדרת הגבול (הגדרה 2.9) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0\\)</span>.</span></p>\n<p><strong>שלב 1: מציאת <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> מהרציפות במידה שווה.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> לפי הגדרה 5.46 קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כך שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y-x|&lt;\\delta \\implies |f(y)-f(x)|&lt;\\varepsilon.\\]</div>\n<p><em>למה?</em> הדלתא שמגיעה מרציפות במ&quot;ש אינה תלויה במקום שבו נמצאים האיברים <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y_n\\)</span></span> — היא עובדת בו-זמנית לכל הציר.</p>\n<p><strong>שלב 2: מציאת <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> מהתכנסות הפרש הקלטים.</strong> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span>,</span></span> מהגדרת גבול של סדרה (הגדרה 2.9) עבור המספר החיובי <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|(y_n-x_n)-0|&lt;\\delta, \\quad\\text{כלומר}\\quad |y_n-x_n|&lt;\\delta.\\]</div>\n<p><strong>שלב 3: הסקת ההתכנסות של הפרש הפלטים.</strong> מאחר שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in\\mathbb R\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|y_n-x_n|&lt;\\delta\\)</span>,</span> משלב 1 נובע כי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|(f(y_n)-f(x_n))-0|=|f(y_n)-f(x_n)|&lt;\\varepsilon.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span></span> היה שרירותי, הוכחנו לפי הגדרה 2.9 כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0\\)</span>.</span></p></div></div>","steps":["<p>תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n),(y_n)\\)</span> סדרות ממשיות המקיימות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span>.</span> נרצה להוכיח לפי הגדרת הגבול (הגדרה 2.9) כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0\\)</span>.</span></p>\n<p><strong>שלב 1: מציאת <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> מהרציפות במידה שווה.</strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> לפי הגדרה 5.46 קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כך שלכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y-x|&lt;\\delta \\implies |f(y)-f(x)|&lt;\\varepsilon.\\]</div>\n<p><em>למה?</em> הדלתא שמגיעה מרציפות במ&quot;ש אינה תלויה במקום שבו נמצאים האיברים <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y_n\\)</span></span> — היא עובדת בו-זמנית לכל הציר.</p>","<p><strong>שלב 2: מציאת <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> מהתכנסות הפרש הקלטים.</strong> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span>,</span></span> מהגדרת גבול של סדרה (הגדרה 2.9) עבור המספר החיובי <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|(y_n-x_n)-0|&lt;\\delta, \\quad\\text{כלומר}\\quad |y_n-x_n|&lt;\\delta.\\]</div>","<p><strong>שלב 3: הסקת ההתכנסות של הפרש הפלטים.</strong> מאחר שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in\\mathbb R\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|y_n-x_n|&lt;\\delta\\)</span>,</span> משלב 1 נובע כי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|(f(y_n)-f(x_n))-0|=|f(y_n)-f(x_n)|&lt;\\varepsilon.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span></span> היה שרירותי, הוכחנו לפי הגדרה 2.9 כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להניח שהסדרות <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((y_n)\\)</span></span> מתכנסות! אין צורך ואסור להניח זאת — ייתכן ששתיהן שואפות לאינסוף (כגון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_n=n, y_n=n+\\frac{1}{n}\\)</span>).</span></li><li>לנסות להפעיל רציפות רגילה (נקודתית): רציפות נקודתית לא מספיקה, כי <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y_n\\)</span></span> לא חייבות להתקרב לנקודה אחת קבועה.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <em>לא</em> רציפה במידה שווה, אפשר לצלם בכל פעם זוג נקודות שהולך ומתקרב אופקית אבל הגובה ביניהן נשאר גדול — וכך מקבלים שתי סדרות שהורסות את הנתון.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <em>לא</em> רציפה במידה שווה, אפשר לצלם בכל פעם זוג נקודות שהולך ומתקרב אופקית אבל הגובה ביניהן נשאר גדול — וכך מקבלים שתי סדרות שהורסות את הנתון.</p>\n<p><strong>תמונה בראש</strong>: דמיינו שאין רציפות במ&quot;ש — זה אומר שיש גובה קפיצה מינימלי (נאמר גובה מדרגה של מטר), שאפשר לייצר אותו במרווחים קטנים יותר ויותר: פעם תוך חצי מטר, פעם תוך שליש מטר, פעם תוך רבע מטר. אם נאסוף את הזוגות האלה לסדרות, המרחק האופקי יתאפס <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בזמן שהקפיצה בפלט תישאר מעל מטר — בניגוד לנתון.</p>\n<p><strong>עם מספרים</strong>: בפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> (ש<em>אינה</em> רציפה במ&quot;ש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>),</span></span> אם ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(x_n=n\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_n=n+\\frac{1}{n}\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n=\\frac{1}{n}\\to 0\\)</span>.</span> אבל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=2\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(2.5)-f(2)=6.25-4=2.25\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=5\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(5.2)-f(5)=27.04-25=2.04\\)</span>.</span> תמיד ההפרש גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span></span> ולכן אינו שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>הוכחה בשלילה</strong> פירושה להניח שהמסקנה שקרית (<span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה במ&quot;ש) ולהראות שזה מתנגש עם הנתון.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> שאינה רציפה במידה שווה. הזיזו את הסליידר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>:</span> שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\((n,n^2)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((n+\\frac{1}{n},(n+\\frac{1}{n})^2)\\)</span></span> הולכות ומתקרבות אופקית (הקווים האנכיים צמודים), אבל הפרש הגבהים ביניהן תמיד נשאר גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.5,&quot;xmax&quot;:7,&quot;ymin&quot;:-2,&quot;ymax&quot;:45}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:6,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x^{2}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n+\\\\frac{1}{n},f(n+\\\\frac{1}{n}))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;lx&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=n&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;ly&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=n+\\\\frac{1}{n}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איך מנסחים את שלילת הרציפות במידה שווה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איך מנסחים את שלילת הרציפות במידה שווה</p><div class=\"callout-body\"><p>בדיוק כמו בהוכחת משפט קנטור (משפט 5.48): אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> שעבורו <em>שום</em> <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> לא מצליח.</p></div></div>"},{"title":"רמז 2: בוחרים $\\delta=\\frac{1}{n}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}\\)</span></p><div class=\"callout-body\"><p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> הפעילו את השלילה עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}\\)</span>.</span> מה מקבלים?</p></div></div>"},{"title":"רמז 3: סתירה מידית לנתון (בלי בולצאנו-ויירשטראס!)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: סתירה מידית לנתון (בלי בולצאנו-ויירשטראס!)</p><div class=\"callout-body\"><p>הוכיחו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n\\to 0\\)</span></span> (בעזרת הסנדוויץ׳). מדוע התנאי <span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|\\ge\\varepsilon_0\\)</span> סותר כעת את הנתון בשאלה? שימו לב שכאן <strong>לא</strong> צריך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span></span> תהיה חסומה, כי הנתון מדבר על <strong>כל</strong> זוג סדרות כזה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>!</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נניח בשלילה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span> משלילת ההגדרה נקבל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> קבוע, ועבור כל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}\\)</span> נבחר זוג נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in\\mathbb R\\)</span> שקרובות עד <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span> אך תמונותיהן רחוקות לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>.</span> מכאן <span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n\\to 0\\)</span> אך <span class=\"math math-inline\" dir=\"ltr\">\\(f(y_n)-f(x_n)\\)</span> אינו שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> בסתירה לנתון.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הנחת השלילה וניסוחה הפורמלי.</strong> נניח בשלילה כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span> שלילת הגדרה 5.46 אומרת שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימות נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in\\mathbb R\\)</span> המקיימות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y-x|&lt;\\delta \\quad\\text{וגם}\\quad |f(y)-f(x)|\\ge\\varepsilon_0.\\]</div>\n<p><em>למה?</em> להגיד ש&quot;אין <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> שעובד <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span></span>&quot; פירושו שכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> שננסה ניכשל עליו, כלומר נמצא זוג נקודות קרוב <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> שהגרף קופץ ביניהן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span></span> או יותר.</p>\n<p><strong>שלב 2: בניית הסדרות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_n),(y_n)\\)</span>.</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> נציב <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}&gt;0\\)</span> בהנחת השלילה משלב 1. נקבל שקיימות שתי נקודות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> שאותן נסמן <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_n\\)</span>,</span></span> המקיימות לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y_n-x_n|&lt;\\frac{1}{n} \\quad\\text{וגם}\\quad |f(y_n)-f(x_n)|\\ge\\varepsilon_0.\\]</div>\n<p><strong>שלב 3: בדיקת ההתכנסות והגעה לסתירה.</strong> מהתנאי הראשון נובע לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-\\frac{1}{n}&lt;y_n-x_n&lt;\\frac{1}{n}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{n}=0\\)</span></span> (טענה 2.10), לפי משפט הסנדוויץ׳ (משפט 2.32) נקבל כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span>.</span></p>\n<p>לכן על פי הנתון בסעיף ב, חייב להתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0.\\]</div>\n<p>פירוש הדבר לפי הגדרה 2.9 (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\varepsilon_0&gt;0\\)</span>)</span> שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|&lt;\\varepsilon_0\\)</span>.</span> אולם לפי שלב 2, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|\\ge\\varepsilon_0\\)</span>.</span> סתירה!</p>\n<p><strong>שלב 4: מסקנה.</strong> ההנחה בשלילה שגויה, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p></div></div>","steps":["<p><strong>שלב 1: הנחת השלילה וניסוחה הפורמלי.</strong> נניח בשלילה כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span> שלילת הגדרה 5.46 אומרת שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימות נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in\\mathbb R\\)</span> המקיימות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y-x|&lt;\\delta \\quad\\text{וגם}\\quad |f(y)-f(x)|\\ge\\varepsilon_0.\\]</div>\n<p><em>למה?</em> להגיד ש&quot;אין <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> שעובד <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span></span>&quot; פירושו שכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> שננסה ניכשל עליו, כלומר נמצא זוג נקודות קרוב <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> שהגרף קופץ ביניהן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span></span> או יותר.</p>","<p><strong>שלב 2: בניית הסדרות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x_n),(y_n)\\)</span>.</span></strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> נציב <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}&gt;0\\)</span> בהנחת השלילה משלב 1. נקבל שקיימות שתי נקודות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>,</span></span> שאותן נסמן <span class=\"math math-inline\" dir=\"ltr\">\\(x_n\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_n\\)</span>,</span></span> המקיימות לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y_n-x_n|&lt;\\frac{1}{n} \\quad\\text{וגם}\\quad |f(y_n)-f(x_n)|\\ge\\varepsilon_0.\\]</div>","<p><strong>שלב 3: בדיקת ההתכנסות והגעה לסתירה.</strong> מהתנאי הראשון נובע לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[-\\frac{1}{n}&lt;y_n-x_n&lt;\\frac{1}{n}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{1}{n}=0\\)</span></span> (טענה 2.10), לפי משפט הסנדוויץ׳ (משפט 2.32) נקבל כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}(y_n-x_n)=0\\)</span>.</span></p>\n<p>לכן על פי הנתון בסעיף ב, חייב להתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}(f(y_n)-f(x_n))=0.\\]</div>\n<p>פירוש הדבר לפי הגדרה 2.9 (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\varepsilon_0&gt;0\\)</span>)</span> שקיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|&lt;\\varepsilon_0\\)</span>.</span> אולם לפי שלב 2, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(y_n)-f(x_n)|\\ge\\varepsilon_0\\)</span>.</span> סתירה!</p>","<p><strong>שלב 4: מסקנה.</strong> ההנחה בשלילה שגויה, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span></span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לנסות להפעיל כאן את משפט בולצאנו-ויירשטראס על <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> כמו בהוכחת משפט קנטור: בקטע <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> אינו חסום ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> לא חייבת להיות חסומה! למרבה המזל כאן לא צריך להוכיח רציפות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>,</span> אלא ישירות להסתמך על הנתון של סעיף ב.</li><li>לשלול לא נכון את כמתֵי הרציפות במידה שווה (למשל לכתוב &quot;לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>&quot; במקום &quot;קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span>&quot;).</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"4":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) <strong>א.</strong> (10 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה המתכנסת לגבול חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span> הוכיחו כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{a_n}=1\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x &gt; x + \\frac{x^3}{6}\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשמוציאים שורש מסדר גדול והולך ממספרים שמתקרבים לקבוע חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>,</span> מקבלים משהו שנלחץ מכל הכיוונים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשמוציאים שורש מסדר גדול והולך ממספרים שמתקרבים לקבוע חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>,</span> מקבלים משהו שנלחץ מכל הכיוונים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: אם סדרה מתקרבת לגובה חיובי <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> (נאמר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=4\\)</span>),</span> החל ממקום מסוים כל האיברים שלה כלואים בחלון סגור של מספרים חיוביים (נאמר בין <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>).</span></span> אבל אנחנו כבר יודעים שהשורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> של כל מספר חיובי קבוע שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!</span></span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span> תקועה בין <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{2}\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{6}\\)</span>,</span></span> ששתיהן מתנקזות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2+\\frac{1}{n}\\to 2\\)</span>.</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\le a_n\\le 3\\)</span>.</span> לכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{1}\\le\\sqrt[n]{a_n}\\le\\sqrt[n]{3}\\)</span>:</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(n=10\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\le\\sqrt[10]{2.1}\\approx 1.077\\le\\sqrt[10]{3}\\approx 1.116\\)</span>;</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(n=100\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\le\\sqrt[100]{2.01}\\approx 1.007\\le\\sqrt[100]{3}\\approx 1.011\\)</span>.</span></p>\n<p><strong>שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span>)</span></strong> מוגדר עבור <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge 0\\)</span> (ובהוכחה שלנו החל ממקום מסוים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;\\frac{L}{2}&gt;0\\)</span>,</span> כך שאין בעיית תחום הגדרה לשורש גם עבור <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> זוגיים).</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>באדום הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\((2+\\frac{\\sin x}{x})^{1/x}\\)</span> (דוגמה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\)</span></span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to 2\\)</span>),</span> בין החסם התחתון <span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span> (בירוק, מתאים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{L/2}\\)</span></span> שלם או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^{1/x}\\)</span>)</span> לבין החסם העליון <span class=\"math math-inline\" dir=\"ltr\">\\(3^{1/x}\\)</span> (בכחול, מתאים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{3L/2}\\)</span>).</span></span> הזיזו את הסליידר <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> וראו איך שלושתן מתכנסות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.5,&quot;xmax&quot;:22,&quot;ymin&quot;:0.7,&quot;ymax&quot;:2.1}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=4&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:2,&quot;max&quot;:20,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=(2+\\\\frac{\\\\sin(x)}{x})^{\\\\frac{1}{x}}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;u(x)=3^{\\\\frac{1}{x}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pn&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pu&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,u(n))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איך מרחיקים את $a_n$ מאפס","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איך מרחיקים את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מאפס</p><div class=\"callout-body\"><p>נתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L&gt;0\\)</span>.</span> הפעילו את הגדרת הגבול (הגדרה 2.9) עם הבחירה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}&gt;0\\)</span>!</span></p></div></div>"},{"title":"רמז 2: הוצאת שורש $n$-י על אי-שוויון","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הוצאת שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י על אי-שוויון</p><div class=\"callout-body\"><p><span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}&lt;a_n&lt;\\frac{3L}{2}\\)</span></span> (שלושה מספרים חיוביים), אפשר להוציא שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י מכל שלושת האגפים והסדר נשמר.</p></div></div>"},{"title":"רמז 3: טענה ידועה + סנדוויץ׳","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: טענה ידועה + סנדוויץ׳</p><div class=\"callout-body\"><p>באיזה משפט מהחוברת יודעים <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\sqrt[n]{c}=1\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>?</span> (טענה 2.34). וזכרו ששינוי או אי-הגדרה של מספר סופי של איברים בהתחלה אינו משפיע על הגבול (משפט 2.17).</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}&gt;0\\)</span> בהגדרת הגבול של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to L\\)</span>,</span> וכך נכלא את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בין שני קבועים חיוביים <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}\\)</span></span> החל מאינדקס <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span>.</span> נוציא שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י מכל האגפים, נשתמש בעובדה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{c}\\to 1\\)</span></span> לכל קבוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>,</span> ונסיק מכלל הסנדוויץ׳ <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt[n]{a_n}\\to 1\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: חסימת <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בין שני קבועים חיוביים.</strong> נתון <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;0\\)</span>.</span> ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}&gt;0\\)</span>.</span> לפי הגדרת גבול סדרה (הגדרה 2.9), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L|&lt;\\frac{L}{2}\\)</span>,</span> כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L-\\frac{L}{2}&lt;a_n&lt;L+\\frac{L}{2} \\implies 0&lt;\\frac{L}{2}&lt;a_n&lt;\\frac{3L}{2}.\\]</div>\n<p><em>למה?</em> לפני שמוציאים שורש, חייבים לדעת <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> ממש חיובי (ולא רק שאין ספק לגבי זוגיות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>),</span> וגם רוצים לחסום את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בין שני מספרים קבועים וחיוביים שלא תלויים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></span> בחירה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}\\)</span> מרחיקה אותנו מאפס ומשיגה את שניהם במכה אחת.</p>\n<p><strong>שלב 2: הוצאת שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י ושימוש בגבול השורש של קבוע.</strong> כיוון שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> שלושת האיברים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}\\)</span></span> חיוביים, ופונקציית השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י עולה ממש על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> מתקיים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt[n]{\\frac{L}{2}}&lt;\\sqrt[n]{a_n}&lt;\\sqrt[n]{\\frac{3L}{2}}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}&gt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}&gt;0\\)</span></span> הם קבועים חיוביים, מטענה 2.34 מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\sqrt[n]{\\frac{L}{2}}=1 \\quad\\text{וגם}\\quad \\lim_{n\\to\\infty}\\sqrt[n]{\\frac{3L}{2}}=1.\\]</div>\n<p><strong>שלב 3: הפעלת משפט הסנדוויץ׳.</strong> מאחר שגבול סדרה נקבע לפי &quot;זנב&quot; הסדרה בלבד (משפט 2.17, איברים עד <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> אינם משנים את ההתכנסות או את הגבול), משפט הסנדוויץ׳ (משפט 2.32) על הזנב <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> נותן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\sqrt[n]{a_n}=1.\\]</div></div></div>","steps":["<p><strong>שלב 1: חסימת <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בין שני קבועים חיוביים.</strong> נתון <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L\\)</span> כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L&gt;0\\)</span>.</span> ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}&gt;0\\)</span>.</span> לפי הגדרת גבול סדרה (הגדרה 2.9), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L|&lt;\\frac{L}{2}\\)</span>,</span> כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L-\\frac{L}{2}&lt;a_n&lt;L+\\frac{L}{2} \\implies 0&lt;\\frac{L}{2}&lt;a_n&lt;\\frac{3L}{2}.\\]</div>\n<p><em>למה?</em> לפני שמוציאים שורש, חייבים לדעת <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> ממש חיובי (ולא רק שאין ספק לגבי זוגיות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>),</span> וגם רוצים לחסום את <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> בין שני מספרים קבועים וחיוביים שלא תלויים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></span> בחירה של <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{L}{2}\\)</span> מרחיקה אותנו מאפס ומשיגה את שניהם במכה אחת.</p>","<p><strong>שלב 2: הוצאת שורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י ושימוש בגבול השורש של קבוע.</strong> כיוון שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> שלושת האיברים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}\\)</span></span> חיוביים, ופונקציית השורש <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span>-י עולה ממש על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> מתקיים לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt[n]{\\frac{L}{2}}&lt;\\sqrt[n]{a_n}&lt;\\sqrt[n]{\\frac{3L}{2}}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}&gt;0\\)</span></span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3L}{2}&gt;0\\)</span></span> הם קבועים חיוביים, מטענה 2.34 מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\sqrt[n]{\\frac{L}{2}}=1 \\quad\\text{וגם}\\quad \\lim_{n\\to\\infty}\\sqrt[n]{\\frac{3L}{2}}=1.\\]</div>","<p><strong>שלב 3: הפעלת משפט הסנדוויץ׳.</strong> מאחר שגבול סדרה נקבע לפי &quot;זנב&quot; הסדרה בלבד (משפט 2.17, איברים עד <span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span> אינם משנים את ההתכנסות או את הגבול), משפט הסנדוויץ׳ (משפט 2.32) על הזנב <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N\\)</span> נותן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\sqrt[n]{a_n}=1.\\]</div>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לכתוב ישירות &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim \\sqrt[n]{a_n}=\\lim a_n^{1/n}=L^0=1\\)</span>&quot; — המשפט על <span class=\"math math-inline\" dir=\"ltr\">\\(b_n^{c_n}\\to b^c\\)</span> (טענה 6.15) נכון בגרסה הרציונלית/ממשית כשהמעריך מתכנס למספר והבסיס חיובי, אך בשאלה הזו (יחידה 2, לפני הגדרת חזקה ממשית) רוצים הוכחה יסודית בעזרת סנדוויץ׳ וטענה 2.34, בלי הנחות על האיברים הראשונים.</li><li>לבחור בטעות את החסם התחתון <span class=\"nobr\">כ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{L}{2}\\)</span>:</span> אם משתמשים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n&lt;\\frac{3L}{2}\\)</span>,</span></span> הסדרה בצד שמאל היא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> (ולא שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!),</span></span> והסנדוויץ׳ לא נסגר.</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\"><span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> שני הביטויים שווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> אבל בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> הצד של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> עולה מהר יותר מהצד של הפולינום, ולכן תמיד מנצח אותו.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> שני הביטויים שווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> אבל בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> הצד של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> עולה מהר יותר מהצד של הפולינום, ולכן תמיד מנצח אותו.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על שני רצים שיוצאים בדיוק מאותו קו זינוק בזמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>:</span> שניהם מתחילים במרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> אם המהירות (הנגזרת) של רץ א׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span>)</span> גדולה <em>בכל רגע</em> מהמהירות של רץ ב׳ <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x+\\frac{x^3}{6}\\)</span>),</span> אז בכל שנייה אחרי הזינוק רץ א׳ בהכרח נמצא קדימה יותר מרץ ב׳!</p>\n<p><strong>עם מספרים</strong>: נציב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac{1}{2}\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin(\\frac{1}{2})=\\frac{\\pi}{6}\\approx 0.5236\\)</span>,</span> לעומת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}+\\frac{(1/2)^3}{6}=\\frac{1}{2}+\\frac{1}{48}=\\frac{25}{48}\\approx 0.5208\\)</span>.</span> כבר כאן <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin(\\frac{1}{2})\\)</span> גדול יותר, והפער גדל ככל שמתקדמים לכיוון <span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span> (<span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> יש <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}\\approx 1.571\\)</span> מול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+\\frac{1}{6}\\approx 1.167\\)</span>).</span></p>\n<p><strong>פונקציה עולה ממש</strong> פירושה שככל שהולכים ימינה על ציר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span> ערך הפונקציה גדל. המשפט שנותן זאת אומר שאם הנגזרת של פונקציה רציפה חיובית ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span> הפונקציה עולה ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הגרף של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> ובאדום הפולינום <span class=\"math math-inline\" dir=\"ltr\">\\(x+\\frac{x^3}{6}\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> הם מתחילים יחד <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>,</span></span> ובכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> העקומה הכחולה מעל האדומה. הזיזו את הסליידר <span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span> כדי להשוות את הגבהים.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.15,&quot;ymin&quot;:-0.1,&quot;ymax&quot;:1.7}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=0.7&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:0.95,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\arcsin(x)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=x+\\\\frac{x^{3}}{6}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,g(t))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מעבירים אגף לפונקציית הפרש","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מעבירים אגף לפונקציית הפרש</p><div class=\"callout-body\"><p>הגדירו <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\arcsin x - x - \\frac{x^3}{6}\\)</span> על הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> מה הערך של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0)\\)</span>?</span></p></div></div>"},{"title":"רמז 2: מחשבים את $g'(x)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מחשבים את <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span></p><div class=\"callout-body\"><p>הנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span></span> היא <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}\\)</span> (משפט 7.28). מצאו את <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span></p></div></div>"},{"title":"רמז 3: איך מראים ש-$g'(x)>0$ בלי להסתבך","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: איך מראים <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span></span> בלי להסתבך</p><div class=\"callout-body\"><p>צריך להראות שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}&gt;1+\\frac{x^2}{2}\\)</span>.</span> נסו להכפיל <span class=\"math math-inline\" dir=\"ltr\">\\((1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2\\)</span> ולפתוח סוגריים — מה נשאר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגדיר את פונקציית ההפרש <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\arcsin x-x-\\frac{x^3}{6}\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> נוודא <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (לרבות בקצוות) וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> נראה בעזרת אלגברה פשוטה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span> ומכך נסיק ממשפט 8.18 <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> עולה ממש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)&gt;g(0)=0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הגדרת פונקציית ההפרש ובדיקת רציפות וגזירות.</strong> נגדיר על הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> את הפונקציה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x)=\\arcsin x-x-\\frac{x^3}{6}.\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> מוגדרת ורציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\([-1,1]\\)</span> ובפרט <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (הגדרה 5.45), והפולינום <span class=\"math math-inline\" dir=\"ltr\">\\(x+\\frac{x^3}{6}\\)</span> רציף וגזיר בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> לפיכך <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></span> כמו כן, <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> גזירה בכל הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span> (משפט 7.28) ובפרט <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> ונגזרתה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span> ומכללי הגזירה (משפטים 7.13–7.16) נקבל לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{1}{\\sqrt{1-x^2}}-1-\\frac{3x^2}{6}=\\frac{1}{\\sqrt{1-x^2}}-\\left(1+\\frac{x^2}{2}\\right).\\]</div>\n<p><strong>שלב 2: הוכחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span></strong> נבחן את הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\((1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2=(1-x^2)\\left(1+x^2+\\frac{x^4}{4}\\right)=1+x^2+\\frac{x^4}{4}-x^2-x^4-\\frac{x^6}{4}=1-\\frac{3}{4}x^4-\\frac{1}{4}x^6.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3}{4}x^4+\\frac{1}{4}x^6&gt;0\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2&lt;1.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-x^2&gt;0\\)</span>,</span> ואפשר לחלק בו בלי לשנות את כיוון אי-השוויון:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left(1+\\frac{x^2}{2}\\right)^2&lt;\\frac{1}{1-x^2}.\\]</div>\n<p>שני האגפים חיוביים, והוצאת שורש ריבועי (פונקציה עולה ממש) נותנת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[1+\\frac{x^2}{2}&lt;\\frac{1}{\\sqrt{1-x^2}}.\\]</div>\n<p>מכאן שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{1}{\\sqrt{1-x^2}}-\\left(1+\\frac{x^2}{2}\\right)&gt;0.\\]</div>\n<p><em>למה?</em> במקום להסתבך עם שרשור תנאי העלאה בריבוע מראש (מותר רק כשהאגפים חיוביים), קל לבדוק ישירות שהמכפלה <span class=\"math math-inline\" dir=\"ltr\">\\((1-x^2)(1+\\frac{x^2}{2})^2\\)</span> יוצאת קטנה ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ולגזור משם לאחור את אי-השוויון הרצוי.</p>\n<p><strong>שלב 3: הסקת האי-שוויון.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> וגזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span> לפי המשפט על סימן הנגזרת ומונוטוניות (משפט 8.18 / מסקנה ממשפט לגראנז׳ 8.6), <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> (מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>)</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x)&gt;g(0)=\\arcsin 0-0-\\frac{0^3}{6}=0.\\]</div>\n<p>כלומר, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x-x-\\frac{x^3}{6}&gt;0\\)</span>,</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x&gt;x+\\frac{x^3}{6}\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: הגדרת פונקציית ההפרש ובדיקת רציפות וגזירות.</strong> נגדיר על הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> את הפונקציה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x)=\\arcsin x-x-\\frac{x^3}{6}.\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> מוגדרת ורציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\([-1,1]\\)</span> ובפרט <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (הגדרה 5.45), והפולינום <span class=\"math math-inline\" dir=\"ltr\">\\(x+\\frac{x^3}{6}\\)</span> רציף וגזיר בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span>.</span> לפיכך <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></span> כמו כן, <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> גזירה בכל הקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((-1,1)\\)</span> (משפט 7.28) ובפרט <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> ונגזרתה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span> ומכללי הגזירה (משפטים 7.13–7.16) נקבל לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{1}{\\sqrt{1-x^2}}-1-\\frac{3x^2}{6}=\\frac{1}{\\sqrt{1-x^2}}-\\left(1+\\frac{x^2}{2}\\right).\\]</div>","<p><strong>שלב 2: הוכחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span></strong> נבחן את הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\((1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2=(1-x^2)\\left(1+x^2+\\frac{x^4}{4}\\right)=1+x^2+\\frac{x^4}{4}-x^2-x^4-\\frac{x^6}{4}=1-\\frac{3}{4}x^4-\\frac{1}{4}x^6.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3}{4}x^4+\\frac{1}{4}x^6&gt;0\\)</span>,</span> ולכן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[(1-x^2)\\left(1+\\frac{x^2}{2}\\right)^2&lt;1.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-x^2&gt;0\\)</span>,</span> ואפשר לחלק בו בלי לשנות את כיוון אי-השוויון:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\left(1+\\frac{x^2}{2}\\right)^2&lt;\\frac{1}{1-x^2}.\\]</div>\n<p>שני האגפים חיוביים, והוצאת שורש ריבועי (פונקציה עולה ממש) נותנת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[1+\\frac{x^2}{2}&lt;\\frac{1}{\\sqrt{1-x^2}}.\\]</div>\n<p>מכאן שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{1}{\\sqrt{1-x^2}}-\\left(1+\\frac{x^2}{2}\\right)&gt;0.\\]</div>\n<p><em>למה?</em> במקום להסתבך עם שרשור תנאי העלאה בריבוע מראש (מותר רק כשהאגפים חיוביים), קל לבדוק ישירות שהמכפלה <span class=\"math math-inline\" dir=\"ltr\">\\((1-x^2)(1+\\frac{x^2}{2})^2\\)</span> יוצאת קטנה ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ולגזור משם לאחור את אי-השוויון הרצוי.</p>","<p><strong>שלב 3: הסקת האי-שוויון.</strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> וגזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span> לפי המשפט על סימן הנגזרת ומונוטוניות (משפט 8.18 / מסקנה ממשפט לגראנז׳ 8.6), <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> (מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>)</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x)&gt;g(0)=\\arcsin 0-0-\\frac{0^3}{6}=0.\\]</div>\n<p>כלומר, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x-x-\\frac{x^3}{6}&gt;0\\)</span>,</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x&gt;x+\\frac{x^3}{6}\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להפעיל נגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> בנקודת הקצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\(\\arcsin x\\)</span> אינה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> (השיפוע שם שואף לאינסוף, <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{\\sqrt{1-x^2}}\\)</span> לא מוגדר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>),</span></span> אבל הרציפות בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> והגזירות בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> הן בדיוק כל מה שמשפט 8.18 ו-8.6 דורשים!</li><li>לשכוח לציין שהאי-שוויון <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> בדקנו ספציפית <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> ולא רק להראות <span class=\"math math-inline\" dir=\"ltr\">\\(g''&gt;0\\)</span> בלי לבדוק את רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(g'\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"5":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) תהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\begin{cases}\\dfrac{\\sin(x^2)}{x} &amp; x\\ne 0\\\\ 1 &amp; x=0\\end{cases}\\)</span>.</span> אז: א. <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span> ב. <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי רציפות סליקה. ג. <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי רציפות מסוג ראשון. ד. <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי רציפות מסוג שני.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשמתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> משני הצדדים הגרף מכוון אל הגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> אבל הנקודה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> עצמה הוקפצה אל הגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> — לכן זו אי-רציפות סליקה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשמתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> משני הצדדים הגרף מכוון אל הגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> אבל הנקודה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> עצמה הוקפצה אל הגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> — לכן זו אי-רציפות סליקה.</p>\n<p><strong>תמונה בראש</strong>: דמיינו כביש שעובר בדיוק בגובה הרצפה כשמתקרבים לצומת <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הן משמאל והן מימין, אבל ממש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> מישהו הציב בלטה בגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> אפשר לתקן את הכביש (&quot;לסלק&quot; את התקלה) רק על ידי הזזה של נקודה בודדת אחת לגובה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: נציב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0.1\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin(0.01)}{0.1}\\approx 0.099998\\)</span>.</span> נציב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=-0.1\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin(0.01)}{-0.1}\\approx -0.099998\\)</span>.</span> שני הצדדים מתנקזים בדיוק <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> בזמן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span>.</span></span></p>\n<p><strong>אי-רציפות סליקה</strong> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span></span> היא מצב שבו הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to x_0}f(x)\\)</span> קיים וסופי, אבל אינו שווה לערך <span class=\"math math-inline\" dir=\"ltr\">\\(f(x_0)\\)</span> (או שהפונקציה לא מוגדרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_0\\)</span>).</span></span> <strong>מסוג ראשון</strong> בקורס הזה הוא כשגבולות ימין ושמאל קיימים וסופיים אך שונים זה מזה (קפיצה); <strong>מסוג שני</strong> הוא כשלפחות אחד מהגבולות החד-צדדיים אינו קיים במובן הסופי.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הגרף של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{\\sin(x^2)}{x}\\)</span> ששואף לחור הפתוח <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span></span> משני הצדדים. הנקודה האדומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> היא הערך הבודד <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span> שיוצר את אי-הרציפות הסליקה.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-2.5,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-1.2,&quot;ymax&quot;:1.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{\\\\sin(x^{2})}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;hole&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;val&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,1)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: קישור לגבול המפורסם","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: קישור לגבול המפורסם</p><div class=\"callout-body\"><p>עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span>,</span> נסו להכפיל ולחלק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> כדי לקבל את הביטוי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin(x^2)}{x^2}\\)</span>.</span></p></div></div>"},{"title":"רמז 2: חישוב הגבול ב-$0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: חישוב הגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span></p><div class=\"callout-body\"><p>למה שואף <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin(x^2)}{x^2}\\)</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span></span> (משפט 4.45 עם הרכבה), ולמה שואף הגורם השני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>?</span></p></div></div>"},{"title":"רמז 3: השוואה מול $f(0)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: השוואה מול <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span></p><div class=\"callout-body\"><p>האם הגבול סופי? האם הוא שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span>?</span></span> בדקו מול הגדרות 5.21–5.23.</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נכתוב עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\cdot\\frac{\\sin(x^2)}{x^2}\\)</span>,</span> נחשב את הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)\\)</span> בעזרת משפט 4.45 ואריתמטיקת גבולות, ונשווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\)</span></span> כדי לסווג את נקודת אי-הרציפות לפי הגדרה 5.21.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: חישוב הגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x^2&gt;0\\)</span> (ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>),</span> ואפשר להרחיב את השבר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\frac{\\sin(x^2)}{x}=x\\cdot\\frac{\\sin(x^2)}{x^2}.\\]</div>\n<p>כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(t=x^2\\to 0\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span> בסביבה נקובה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> מהגבול הידוע <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to 0}\\frac{\\sin t}{t}=1\\)</span> (משפט 4.45) ומשפט הרכבת הגבולות (הנובע מאפיון היינה משפט 4.30), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{\\sin(x^2)}{x^2}=1\\)</span>.</span> בנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}x=0\\)</span>.</span> לכן מאריתמטיקה של גבולות (כפל, משפט 4.35 והמשכיו):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}f(x)=0\\cdot 1=0.\\]</div>\n<p><em>למה?</em> אם היינו מציבים סתם <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> במונה ובמכנה נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{0}\\)</span>.</span> ברגע שכותבים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cdot\\frac{\\sin(x^2)}{x^2}\\)</span>,</span> השבר שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> והכופל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> מושך את הכול <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>שלב 2: סיווג הנקודה ושלילת יתר האפשרויות.</strong> מצאנו כי הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0\\)</span> קיים וסופי, ולכן קיימים גם הגבולות החד-צדדיים משמאל ומימין ושווים שניהם <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> אולם נתון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\ne 0\\)</span>:</span></span></p>\n<ul><li>א. שגויה: <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0\\ne 1=f(0)\\)</span>.</span></li><li>ב. <strong>נכונה</strong>: כיוון שהגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> קיים וסופי ושונה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>,</span></span> לפי הגדרה 5.21 <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי-רציפות סליקה.</li><li>ג. שגויה: לפי הגדרה 5.22 בקורס, אי-רציפות מסוג ראשון (קפיצה) היא כאשר הגבולות החד-צדדיים קיימים וסופיים אך <em>שונים</em> זה מזה. כאן הם שווים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0=0\\)</span>).</span></li><li>ד. שגויה: אי-רציפות מסוג שני (הגדרה 5.23) היא כשאחד הגבולות החד-צדדיים אינו קיים במובן הסופי, וכאן שניהם קיימים ושווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li></ul>\n<p><strong>התשובה הנכונה: ב</strong></p></div></div>","steps":["<p><strong>שלב 1: חישוב הגבול <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>.</span></span></strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(x^2&gt;0\\)</span> (ובפרט <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span>),</span> ואפשר להרחיב את השבר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=\\frac{\\sin(x^2)}{x}=x\\cdot\\frac{\\sin(x^2)}{x^2}.\\]</div>\n<p>כאשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>,</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(t=x^2\\to 0\\)</span> וגם <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\ne 0\\)</span> בסביבה נקובה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> מהגבול הידוע <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{t\\to 0}\\frac{\\sin t}{t}=1\\)</span> (משפט 4.45) ומשפט הרכבת הגבולות (הנובע מאפיון היינה משפט 4.30), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}\\frac{\\sin(x^2)}{x^2}=1\\)</span>.</span> בנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}x=0\\)</span>.</span> לכן מאריתמטיקה של גבולות (כפל, משפט 4.35 והמשכיו):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to 0}f(x)=0\\cdot 1=0.\\]</div>\n<p><em>למה?</em> אם היינו מציבים סתם <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> במונה ובמכנה נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0}{0}\\)</span>.</span> ברגע שכותבים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\cdot\\frac{\\sin(x^2)}{x^2}\\)</span>,</span> השבר שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> והכופל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> מושך את הכול <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>","<p><strong>שלב 2: סיווג הנקודה ושלילת יתר האפשרויות.</strong> מצאנו כי הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0\\)</span> קיים וסופי, ולכן קיימים גם הגבולות החד-צדדיים משמאל ומימין ושווים שניהם <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> אולם נתון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=1\\ne 0\\)</span>:</span></span></p>\n<ul><li>א. שגויה: <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0}f(x)=0\\ne 1=f(0)\\)</span>.</span></li><li>ב. <strong>נכונה</strong>: כיוון שהגבול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> קיים וסופי ושונה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)\\)</span>,</span></span> לפי הגדרה 5.21 <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> היא נקודת אי-רציפות סליקה.</li><li>ג. שגויה: לפי הגדרה 5.22 בקורס, אי-רציפות מסוג ראשון (קפיצה) היא כאשר הגבולות החד-צדדיים קיימים וסופיים אך <em>שונים</em> זה מזה. כאן הם שווים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0=0\\)</span>).</span></li><li>ד. שגויה: אי-רציפות מסוג שני (הגדרה 5.23) היא כשאחד הגבולות החד-צדדיים אינו קיים במובן הסופי, וכאן שניהם קיימים ושווים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li></ul>\n<p><strong>התשובה הנכונה: ב</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin(x^2)}{x}\\)</span></span> מתנהג כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin x}{x}\\)</span> ושואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ולסמן בטעות א <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה). בפועל הביטוי שמתאים למכנה <span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span> שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ואז עוד מוכפל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to 0\\)</span>.</span></span></li><li>להתבלבל בין הגדרת אי-רציפות סליקה (5.21) לאי-רציפות מסוג ראשון (5.22): בקורס זה הן מוגדרות בנפרד — בסליקה הגבול השלם קיים וסופי ושונה מערך הפונקציה.</li></ul></div></div>"}],"similar":"","mc":{"answer":"ב"}},"6":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) אם <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{a_{n+1}}{a_n}\\)</span> קיים וסופי. א. הטענה נכונה. ב. הטענה אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">העובדה שסדרה שואפת לאינסוף לא מכריחה את היחס בין איבר לאיבר שלפניו להתייצב על מספר אחד קבוע.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: העובדה שסדרה שואפת לאינסוף לא מכריחה את היחס בין איבר לאיבר שלפניו להתייצב על מספר אחד קבוע.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על שתי דרכים לעלות למעלה לאינסוף. דרך אחת: בכל קפיצה מכפילים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span>)</span> — ואז היחס בין הקפיצות עצמו גדל לאינסוף ואינו סופי. דרך שנייה: עולים עם קפיצות בקצב מזגזג — צעד אחד קופץ פי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>,</span> צעד הבא מתכווץ בערך לשליש מהיחס הקודם — כך שעדיין מגיעים לאינסוף אבל היחס <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}\\)</span> רק מזגזג בלי להתכנס בכלל!</p>\n<p><strong>עם מספרים</strong>: בסדרה <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to\\infty\\)</span>,</span> אבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}=\\frac{(n+1)!}{n!}=n+1\\to\\infty\\)</span>,</span> וזה לא סופי! בדוגמה מתנדנדת: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=1, a_2=6, a_3=3, a_4=12, a_5=5,\\dots\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n\\cdot(2+(-1)^n)\\)</span>:</span> תמיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge n\\to\\infty\\)</span>,</span> אבל המנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}\\)</span> קופצת לסירוגין קרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> (כשעוברים מאי-זוגי לזוגי) וקרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{3}\\)</span></span> (כשעוברים מזוגי לאי-זוגי).</p>\n<p><strong>גבול קיים וסופי</strong> של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}\\)</span> פירושו שכל המנות העוקבות מתקרבות למספר ממשי יחיד <span class=\"math math-inline\" dir=\"ltr\">\\(L\\in\\mathbb R\\)</span> — לא בורחות לאינסוף ולא קופצות בין כמה ערכים.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול העקומה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x(2+\\cos(\\pi x))\\)</span> שעוברת בדיוק בנקודות הדוגמה הנגדית <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n(2+(-1)^n)\\)</span> — היא תמיד מעל הישר הירוק <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> ולכן שואפת לאינסוף. הנקודה האדומה והכתומה מראות זוג איברים עוקבים <span class=\"math math-inline\" dir=\"ltr\">\\((n,a_n)\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((n+1,a_{n+1})\\)</span>:</span></span> הזיזו את הסליידר <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מזוגי לאי-זוגי ותראו איך היחס ביניהם מזנק בין קרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> לבין קרוב <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{3}\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0,&quot;xmax&quot;:11,&quot;ymin&quot;:-1,&quot;ymax&quot;:32}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=3&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:9,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x(2+\\\\cos(\\\\pi x))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;env&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n+1,f(n+1))&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: נסו לבדוק סדרות מהירות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: נסו לבדוק סדרות מהירות</p><div class=\"callout-body\"><p>מה קורה למנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}\\)</span> עבור סדרה שגדלה מהר מאוד, כמו <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^{n^2}\\)</span>?</span></p></div></div>"},{"title":"רמז 2: ומה עם זיגזוג","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: ומה עם זיגזוג</p><div class=\"callout-body\"><p>נסו לבנות סדרה שגדלה בקפיצות לא אחידות, למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n\\cdot(2+(-1)^n)\\)</span>.</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפריך את הטענה באמצעות שתי דוגמאות נגדיות מפורשות (למשל <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span> שבה הגבול של המנה הוא אינסופי, <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n(2+(-1)^n)\\)</span></span> שבה המנה כלל אינה מתכנסת).</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: דוגמה נגדית פשוטה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span>).</span></strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}n=\\infty\\)</span>,</span></span> ממשפט השוואה לגבול אינסופי (משפט 2.45) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}a_n=\\infty.\\]</div>\n<p>אולם המנה של איברים עוקבים היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{a_{n+1}}{a_n}=\\frac{(n+1)!}{n!}=n+1 \\xrightarrow{n\\to\\infty} \\infty.\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{a_{n+1}}{a_n}\\)</span> אינו סופי (שואף לאינסוף), ודי בכך כדי להפריך את הטענה.</p>\n<p><strong>שלב 2: דוגמה שבה הגבול כלל אינו קיים (אפילו במובן הרחב).</strong> אם נבחן את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n(2+(-1)^n)\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2+(-1)^n\\ge 1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge n\\to\\infty\\)</span>,</span> כלומר גם כאן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span> (משפט 2.45). אבל:</p>\n<ul><li>עבור אינדקסים אי-זוגיים <span class=\"math math-inline\" dir=\"ltr\">\\(n=2k-1\\)</span> (אז <span class=\"math math-inline\" dir=\"ltr\">\\(n+1=2k\\)</span> זוגי):</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{a_{2k}}{a_{2k-1}}=\\frac{3\\cdot 2k}{1\\cdot(2k-1)}=\\frac{6k}{2k-1}\\xrightarrow{k\\to\\infty} 3.\\]</div>\n<ul><li>עבור אינדקסים זוגיים <span class=\"math math-inline\" dir=\"ltr\">\\(n=2k\\)</span> (אז <span class=\"math math-inline\" dir=\"ltr\">\\(n+1=2k+1\\)</span> אי-זוגי):</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{a_{2k+1}}{a_{2k}}=\\frac{1\\cdot(2k+1)}{3\\cdot 2k}=\\frac{2k+1}{6k}\\xrightarrow{k\\to\\infty} \\frac{1}{3}.\\]</div>\n<p>לסדרת המנות יש שתי תתי-סדרות המתכנסות לגבולות שונים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{3}\\)</span>),</span></span> ולכן לפי משפט 3.25 הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{a_{n+1}}{a_n}\\)</span> כלל אינו קיים (לא במובן הצר ולא במובן הרחב).</p>\n<p><em>למה?</em> זוג הדוגמאות מראה שהגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}\\)</span> לא חייב להיות סופי משתי סיבות אפשריות: הוא יכול להיות <span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span> (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n!\\)</span>),</span> ויכול גם לא להיות קיים בכלל (כמו זיגזוג).</p>\n<p><strong>התשובה הנכונה: ב</strong></p></div></div>","steps":["<p><strong>שלב 1: דוגמה נגדית פשוטה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span>).</span></strong> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n!\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>.</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> ומכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}n=\\infty\\)</span>,</span></span> ממשפט השוואה לגבול אינסופי (משפט 2.45) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}a_n=\\infty.\\]</div>\n<p>אולם המנה של איברים עוקבים היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{a_{n+1}}{a_n}=\\frac{(n+1)!}{n!}=n+1 \\xrightarrow{n\\to\\infty} \\infty.\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{a_{n+1}}{a_n}\\)</span> אינו סופי (שואף לאינסוף), ודי בכך כדי להפריך את הטענה.</p>","<p><strong>שלב 2: דוגמה שבה הגבול כלל אינו קיים (אפילו במובן הרחב).</strong> אם נבחן את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n(2+(-1)^n)\\)</span>,</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2+(-1)^n\\ge 1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\ge n\\to\\infty\\)</span>,</span> כלומר גם כאן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=\\infty\\)</span> (משפט 2.45). אבל:</p>\n<ul><li>עבור אינדקסים אי-זוגיים <span class=\"math math-inline\" dir=\"ltr\">\\(n=2k-1\\)</span> (אז <span class=\"math math-inline\" dir=\"ltr\">\\(n+1=2k\\)</span> זוגי):</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{a_{2k}}{a_{2k-1}}=\\frac{3\\cdot 2k}{1\\cdot(2k-1)}=\\frac{6k}{2k-1}\\xrightarrow{k\\to\\infty} 3.\\]</div>\n<ul><li>עבור אינדקסים זוגיים <span class=\"math math-inline\" dir=\"ltr\">\\(n=2k\\)</span> (אז <span class=\"math math-inline\" dir=\"ltr\">\\(n+1=2k+1\\)</span> אי-זוגי):</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{a_{2k+1}}{a_{2k}}=\\frac{1\\cdot(2k+1)}{3\\cdot 2k}=\\frac{2k+1}{6k}\\xrightarrow{k\\to\\infty} \\frac{1}{3}.\\]</div>\n<p>לסדרת המנות יש שתי תתי-סדרות המתכנסות לגבולות שונים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{3}\\)</span>),</span></span> ולכן לפי משפט 3.25 הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{a_{n+1}}{a_n}\\)</span> כלל אינו קיים (לא במובן הצר ולא במובן הרחב).</p>\n<p><em>למה?</em> זוג הדוגמאות מראה שהגבול של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{a_{n+1}}{a_n}\\)</span> לא חייב להיות סופי משתי סיבות אפשריות: הוא יכול להיות <span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span> (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n!\\)</span>),</span> ויכול גם לא להיות קיים בכלל (כמו זיגזוג).</p>\n<p><strong>התשובה הנכונה: ב</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב על הסדרות השכיחות <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=n\\)</span> (שם המנה שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>)</span></span> או <span class=\"math math-inline\" dir=\"ltr\">\\(a_n=2^n\\)</span> (שם המנה שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>)</span></span> ולהניח שזו תופעה כללית.</li><li>להתבלבל עם הכיוון ההפוך החלקי של מבחן המנה: אם <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\frac{a_{n+1}}{a_n}=L&gt;1\\)</span> (בסדרה חיובית) אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to\\infty\\)</span>,</span> אבל ההפך אינו נכון!</li></ul></div></div>"}],"similar":"","mc":{"answer":"ב"}},"7":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה חסומה בעלת <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים, <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> סדרה חסומה בעלת <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> גבולות חלקיים. נסמן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(r\\)</span></span> את מספר הגבולות החלקיים של הסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)\\)</span>.</span> אז: א. תמיד (עבור כל זוג סדרות שכאלה) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=5\\)</span>.</span> ב. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 5\\)</span>,</span> יש מקרים בהם <span class=\"math math-inline\" dir=\"ltr\">\\(r=5\\)</span> ויש מקרים בהם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;5\\)</span>.</span> ג. תמיד (עבור כל זוג סדרות שכאלה) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>.</span> ד. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>,</span> יש מקרים בהם <span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span> ויש מקרים בהם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;6\\)</span>.</span></p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כל גבול חלקי של הסכום <span class=\"math math-inline\" dir=\"ltr\">\\(a_n+b_n\\)</span> חייב להיות סכום של גבול חלקי <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> ועוד גבול חלקי <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> — יש לכל היותר <span class=\"math math-inline\" dir=\"ltr\">\\(2\\times 3=6\\)</span> זוגות כאלה, לפעמים כולם מתקבלים ולפעמים חלק מתנגשים או מדלגים.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כל גבול חלקי של הסכום <span class=\"math math-inline\" dir=\"ltr\">\\(a_n+b_n\\)</span> חייב להיות סכום של גבול חלקי <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> ועוד גבול חלקי <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> — יש לכל היותר <span class=\"math math-inline\" dir=\"ltr\">\\(2\\times 3=6\\)</span> זוגות כאלה, לפעמים כולם מתקבלים ולפעמים חלק מתנגשים או מדלגים.</p>\n<p><strong>תמונה בראש</strong>: דמיינו <span class=\"nobr\">שב-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> יש <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> תחנות שמהן לוקחים מספרים שוב ושוב (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,10\\}\\)</span>),</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> יש <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> תחנות (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2\\}\\)</span>).</span> בכל שלב מחברים תחנה אחת <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> עם אחת <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span>.</span></span> סך כל הצירופים האפשריים הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\times 3=6\\)</span>.</span> אם הסדרות &quot;נפגשות&quot; בכל ששת הצירופים מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>;</span> אבל אם הן מסונכרנות ככה שחלק מהזיווגים לעולם לא קורים (או נותנים אותו סכום!), מספר התחנות בסכום יהיה קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>:</p>\n<ul><li>כדי לקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>:</span> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מחזורית באורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\((0,0,0,10,10,10,\\dots)\\)</span> (גבולות חלקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,10\\}\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> מחזורית באורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\((0,1,2,0,1,2,\\dots)\\)</span> (גבולות חלקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2\\}\\)</span>).</span> הסכום מחזורי <span class=\"math math-inline\" dir=\"ltr\">\\((0,1,2,10,11,12,\\dots)\\)</span> — בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> גבולות חלקיים!</li><li>כדי לקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;6\\)</span>:</span> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> מחזורית באורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\((2,0,0,\\dots)\\)</span> (גבולות חלקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,2\\}\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> מחזורית באורך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>:</span> <span class=\"math math-inline\" dir=\"ltr\">\\((0,1,2,\\dots)\\)</span> (גבולות חלקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2\\}\\)</span>).</span> הסכום הוא <span class=\"math math-inline\" dir=\"ltr\">\\((2,1,2,2,1,2,\\dots)\\)</span> — יש לו רק <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,2\\}\\)</span>)!</span></li></ul>\n<p><strong>גבול חלקי</strong> של סדרה הוא גבול של איזשהי תת-סדרה שלה (לפי משפט 3.27, נקודה שבכל סביבה שלה יש אינסוף איברים מהסדרה).</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הסכומים במחזור <span class=\"math math-inline\" dir=\"ltr\">\\(a_n+b_n\\)</span> שמקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> גבולות חלקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,10,11,12\\}\\)</span> (הקווים הכחולים המקווקווים), ובאדום הדוגמה המסונכרנת שבה מתקבלים רק <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,2\\}\\)</span> למרות <span class=\"nobr\">של-<span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span></span> יש <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> <span class=\"nobr\">ול-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span></span> יש <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0.5,&quot;xmax&quot;:10,&quot;ymin&quot;:-1,&quot;ymax&quot;:13.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(2,1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p3&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(3,2)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(4,10)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p5&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(5,11)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p6&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(6,12)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p7&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(7,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p8&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(8,1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p9&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(9,2)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;r1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;r2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(2,1)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;r3&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(3,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;r4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(4,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;r5&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(5,1)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;r6&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(6,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;y0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;y1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;y2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=2&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;y10&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=10&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;y11&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=11&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;y12&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=12&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איך בנוי כל גבול חלקי של $a_n+b_n$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איך בנוי כל גבול חלקי של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n+b_n\\)</span></p><div class=\"callout-body\"><p>נניח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span></span> הוא גבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n_k}+b_{n_k}\\to L\\)</span>.</span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> חסומה — מה נותן עליה בולצאנו-ויירשטראס? ואחרי שעוברים לתת-סדרה מתכנסת שלה, עושים זאת שוב על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>!</span></p></div></div>"},{"title":"רמז 2: מהו החסם העליון למספר התוצאות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מהו החסם העליון למספר התוצאות</p><div class=\"callout-body\"><p>כמה סכומים שונים מהצורה <span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha+\\beta\\)</span> יכולים להיות לכל היותר, <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span></span> נלקח מתוך <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> אפשרויות <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\)</span></span> מתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>?</span></p></div></div>"},{"title":"רמז 3: בודקים אם אפשר לקבל $6$ ואם אפשר פחות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: בודקים אם אפשר לקבל <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> ואם אפשר פחות</p><div class=\"callout-body\"><p>נסו לבנות סדרות מחזוריות: אחת במחזור <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> כדי להגיע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>,</span></span> ואחת במחזור <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> (או ערכים מתאימים) כדי לקבל פחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ראשית נוכיח בעזרת תתי-תתי-סדרות (ובולצאנו-ויירשטראס פעמיים) שכל גבול חלקי של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n+b_n\\)</span> הוא סכום של גבול חלקי של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> וגבול חלקי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_n\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 2\\cdot 3=6\\)</span>.</span> לאחר מכן נציג זוג סדרות שבהן מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>,</span> וזוג אחר שבו מתקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=2&lt;6\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p>נסמן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{\\alpha_1,\\alpha_2\\}\\)</span></span> את קבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(B=\\{\\beta_1,\\beta_2,\\beta_3\\}\\)</span></span> את קבוצת הגבולות החלקיים של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>.</span></p>\n<p><strong>שלב 1: הוכחה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>.</span></span></strong> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> גבול חלקי של הסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)\\)</span>.</span> לכן קיימת תת-סדרה של אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\((n_k)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}(a_{n_k}+b_{n_k})=L\\)</span>.</span></span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span></span> חסומה, גם התת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> חסומה. לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_{k_j}})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span>:</span> כיוון שזו תת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\in A\\)</span>.</span> כעת נתבונן בסדרה המתאימה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_{n_{k_j}})\\)</span>:</span> גם היא חסומה (כתת-סדרה של הסדרה החסומה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>),</span> ולכן שוב לפי משפט 3.32 יש לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((b_{n_{k_{j_m}}})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\in B\\)</span>.</span></p>\n<p>לאורך אותה סדרת אינדקסים אחרונה מתקיים הן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}a_{n_{k_{j_m}}}=\\alpha\\)</span> (כתת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_{k_j}})\\to\\alpha\\)</span>,</span> משפט 3.25) והן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}b_{n_{k_{j_m}}}=\\beta\\)</span>.</span> מאריתמטיקה של גבולות (משפט 2.28) מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{m\\to\\infty}\\left(a_{n_{k_{j_m}}}+b_{n_{k_{j_m}}}\\right)=\\alpha+\\beta.\\]</div>\n<p>מצד שני, זו תת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k}+b_{n_k})\\to L\\)</span>,</span> ולכן ממשפט 3.25 ומיחידות הגבול (משפט 2.12) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\alpha+\\beta\\)</span>.</span> לפיכך כל גבול חלקי של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)\\)</span> שייך לקבוצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A+B=\\{\\alpha+\\beta : \\alpha\\in A,\\ \\beta\\in B\\}\\)</span>,</span> שבה יש לכל היותר <span class=\"math math-inline\" dir=\"ltr\">\\(2\\cdot 3=6\\)</span> איברים. מכאן בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>.</span></p>\n<p><em>למה?</em> כל קלט בסכום חייב &quot;להיפגש&quot; עם חברו באותו אינדקס בדיוק. המעבר לתת-סדרה של תת-סדרה תופס זנב משותף שבו שתי הסדרות מתכנסות יחד — ולכן גם הסכום שלהן מתכנס לסכום הגבולות.</p>\n<p><strong>שלב 2: דוגמה למקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>.</span></strong> נגדיר שתי סדרות מחזוריות במחזור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>:</span></p>\n<ul><li><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)=(0,0,0,10,10,10,0,0,0,10,10,10,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,10\\)</span>.</span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)=(0,1,2,0,1,2,0,1,2,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,1,2\\)</span>.</span></li></ul>\n<p>אז הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)=(0,1,2,10,11,12,0,1,2,10,11,12,\\dots)\\)</span> היא מחזורית עם <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> ערכים שונים שכל אחד מהם מופיע אינסוף פעמים, ולכן יש לה בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span> גבולות חלקיים: <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,10,11,12\\}\\)</span> (כאן כל <span class=\"math math-inline\" dir=\"ltr\">\\(2\\times 3=6\\)</span> הצירופים גם שונים וגם מופיעים אינסוף פעמים).</p>\n<p><strong>שלב 3: דוגמה למקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;6\\)</span>.</span></strong> נגדיר שתי סדרות מחזוריות במחזור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>:</span></p>\n<ul><li><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)=(2,0,0,2,0,0,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,2\\}\\)</span>.</span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)=(0,1,2,0,1,2,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2\\}\\)</span>.</span></li></ul>\n<p>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)=(2,1,2,2,1,2,\\dots)\\)</span> מקבלת רק את הערכים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> אינסוף פעמים, ולכן יש לה בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(r=2&lt;6\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,2\\}\\)</span>.</span></p>\n<p>מכאן שאפשרות ד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>,</span> יש מקרים בהם <span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span> ויש מקרים בהם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;6\\)</span>)</span> היא הנכונה.</p>\n<p><strong>התשובה הנכונה: ד</strong></p></div></div>","steps":["<p>נסמן <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{\\alpha_1,\\alpha_2\\}\\)</span></span> את קבוצת הגבולות החלקיים של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\(B=\\{\\beta_1,\\beta_2,\\beta_3\\}\\)</span></span> את קבוצת הגבולות החלקיים של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>.</span></p>\n<p><strong>שלב 1: הוכחה <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>.</span></span></strong> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> גבול חלקי של הסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)\\)</span>.</span> לכן קיימת תת-סדרה של אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\((n_k)\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}(a_{n_k}+b_{n_k})=L\\)</span>.</span></span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span></span> חסומה, גם התת-סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k})\\)</span> חסומה. לפי משפט בולצאנו-ויירשטראס (משפט 3.32), קיימת לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_{k_j}})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\)</span>:</span> כיוון שזו תת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\alpha\\in A\\)</span>.</span> כעת נתבונן בסדרה המתאימה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_{n_{k_j}})\\)</span>:</span> גם היא חסומה (כתת-סדרה של הסדרה החסומה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>),</span> ולכן שוב לפי משפט 3.32 יש לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((b_{n_{k_{j_m}}})\\)</span> המתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\beta\\in B\\)</span>.</span></p>\n<p>לאורך אותה סדרת אינדקסים אחרונה מתקיים הן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}a_{n_{k_{j_m}}}=\\alpha\\)</span> (כתת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_{k_j}})\\to\\alpha\\)</span>,</span> משפט 3.25) והן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}b_{n_{k_{j_m}}}=\\beta\\)</span>.</span> מאריתמטיקה של גבולות (משפט 2.28) מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{m\\to\\infty}\\left(a_{n_{k_{j_m}}}+b_{n_{k_{j_m}}}\\right)=\\alpha+\\beta.\\]</div>\n<p>מצד שני, זו תת-סדרה של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_{n_k}+b_{n_k})\\to L\\)</span>,</span> ולכן ממשפט 3.25 ומיחידות הגבול (משפט 2.12) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\alpha+\\beta\\)</span>.</span> לפיכך כל גבול חלקי של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)\\)</span> שייך לקבוצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A+B=\\{\\alpha+\\beta : \\alpha\\in A,\\ \\beta\\in B\\}\\)</span>,</span> שבה יש לכל היותר <span class=\"math math-inline\" dir=\"ltr\">\\(2\\cdot 3=6\\)</span> איברים. מכאן בהכרח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>.</span></p>\n<p><em>למה?</em> כל קלט בסכום חייב &quot;להיפגש&quot; עם חברו באותו אינדקס בדיוק. המעבר לתת-סדרה של תת-סדרה תופס זנב משותף שבו שתי הסדרות מתכנסות יחד — ולכן גם הסכום שלהן מתכנס לסכום הגבולות.</p>","<p><strong>שלב 2: דוגמה למקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>.</span></strong> נגדיר שתי סדרות מחזוריות במחזור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span>:</span></p>\n<ul><li><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)=(0,0,0,10,10,10,0,0,0,10,10,10,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,10\\)</span>.</span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)=(0,1,2,0,1,2,0,1,2,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0,1,2\\)</span>.</span></li></ul>\n<p>אז הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)=(0,1,2,10,11,12,0,1,2,10,11,12,\\dots)\\)</span> היא מחזורית עם <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> ערכים שונים שכל אחד מהם מופיע אינסוף פעמים, ולכן יש לה בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span> גבולות חלקיים: <span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,10,11,12\\}\\)</span> (כאן כל <span class=\"math math-inline\" dir=\"ltr\">\\(2\\times 3=6\\)</span> הצירופים גם שונים וגם מופיעים אינסוף פעמים).</p>","<p><strong>שלב 3: דוגמה למקרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;6\\)</span>.</span></strong> נגדיר שתי סדרות מחזוריות במחזור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>:</span></p>\n<ul><li><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)=(2,0,0,2,0,0,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,2\\}\\)</span>.</span></li><li><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)=(0,1,2,0,1,2,\\dots)\\)</span> — חסומה ובעלת <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2\\}\\)</span>.</span></li></ul>\n<p>הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n+b_n)=(2,1,2,2,1,2,\\dots)\\)</span> מקבלת רק את הערכים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> אינסוף פעמים, ולכן יש לה בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(r=2&lt;6\\)</span> גבולות חלקיים: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{1,2\\}\\)</span>.</span></p>\n<p>מכאן שאפשרות ד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 6\\)</span>,</span> יש מקרים בהם <span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span> ויש מקרים בהם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(r&lt;6\\)</span>)</span> היא הנכונה.</p>\n<p><strong>התשובה הנכונה: ד</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחבר את מספרי הגבולות החלקיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2+3=5\\)</span>)</span> במקום לכפול אותם <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(2\\times 3=6\\)</span>),</span> ולסמן בטעות א או ב.</li><li>לחשוב שתמיד כל <span class=\"math math-inline\" dir=\"ltr\">\\(6\\)</span> הצירופים מתקבלים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(r=6\\)</span>,</span> אפשרות ג): מספיק ששני צירופים שונים אינם קורים באותם אינדקסים (או שסכומיהם מתנגשים, למשל <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)+(0,1,2)\\)</span> נותן בין כה לכל היותר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\{0,1,2,3\\}\\)</span>,</span> רק <span class=\"math math-inline\" dir=\"ltr\">\\(4\\)</span> סכומים אפשריים!).</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/40/q8\">2026א · מועד 83, שאלה 8</a></p>","mc":{"answer":"ד"}},"8":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) לכל <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;b&lt;1\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt{1+e^b}-\\sqrt{1+e^a}&lt;\\frac{(b-a)e}{2\\sqrt{2}}.\\]</div>\n<p>א. הטענה נכונה. ב. הטענה אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">המשוואה הזו משווה בין השיפוע הממוצע של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> לבין מספר שגדול יותר מהשיפוע של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בכל נקודה בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — ולכן זה תמיד נכון לפי משפט לגראנז׳.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: המשוואה הזו משווה בין השיפוע הממוצע של <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> לבין מספר שגדול יותר מהשיפוע של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בכל נקודה בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — ולכן זה תמיד נכון לפי משפט לגראנז׳.</p>\n<p><strong>תמונה בראש</strong>: דמיינו מכונית שנוסעת בין שני תמרורים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> בתוך הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> אם מד המהירות שלה בכל רגע שבין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> תמיד נמוך <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e}{2\\sqrt{2}}\\)</span>,</span></span> אז גם המהירות הממוצעת שלה (הפרש המרחק חלקי הפרש הזמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b-a\\)</span>)</span> חייבת להיות נמוכה ממש מהתקרה הזו.</p>\n<p><strong>עם מספרים</strong>: נציב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a=0.1, b=0.9\\)</span>:</span> אגף שמאל הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{1+e^{0.9}}-\\sqrt{1+e^{0.1}}\\approx 1.8600-1.4509=0.4091\\)</span>,</span> והצד הימני הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{0.8\\cdot e}{2\\sqrt{2}}\\approx 0.7688\\)</span>.</span> ואכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.4091&lt;0.7688\\)</span>.</span></p>\n<p><strong>משפט לגראנז׳</strong> קושר בין ההפרש <span class=\"math math-inline\" dir=\"ltr\">\\(f(b)-f(a)\\)</span> לבין ערך הנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span> בנקודה כלשהי <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> בין <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(b)-f(a)=f'(c)(b-a)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span> על <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> (בין הקווים האפורים <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>).</span></span> באדום המיתר המחבר את <span class=\"math math-inline\" dir=\"ltr\">\\((a,f(a))\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b,f(b))\\)</span>,</span></span> ובירוק מקווקו ישר בעל השיפוע המרבי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e}{2\\sqrt{2}}\\)</span>.</span> הזיזו את הסליידרים <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> ותראו שהמיתר האדום תמיד מתון יותר מהקו הירוק.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.15,&quot;ymin&quot;:1.2,&quot;ymax&quot;:2.4}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;a&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;a=0.2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.05,&quot;max&quot;:0.45,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;b&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;b=0.8&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.5,&quot;max&quot;:0.95,&quot;step&quot;:0.05}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\sqrt{1+e^{x}}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;sec&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=f(a)+\\\\frac{f(b)-f(a)}{b-a}(x-a)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;cap&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=f(a)+\\\\frac{e}{2\\\\sqrt{2}}(x-a)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;l0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;l1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pa&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(a,f(a))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;pb&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(b,f(b))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: זיהוי הפונקציה והפרש ערכים","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: זיהוי הפונקציה והפרש ערכים</p><div class=\"callout-body\"><p>הסתכלו על אגף שמאל כהפרש <span class=\"math math-inline\" dir=\"ltr\">\\(f(b)-f(a)\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span>.</span></p></div></div>"},{"title":"רמז 2: הפעלת משפט לגראנז׳","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הפעלת משפט לגראנז׳</p><div class=\"callout-body\"><p><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (ולכן בפרט רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>).</span></span> מה נותן משפט לגראנז׳ (8.6) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>?</span></p></div></div>"},{"title":"רמז 3: חסימת הנגזרת ב-$(0,1)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: חסימת הנגזרת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span></p><div class=\"callout-body\"><p>חשבו את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=\\frac{e^c}{2\\sqrt{1+e^c}}\\)</span>.</span> מדוע לכל <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span> המונה קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></span> והמכנה גדול <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\sqrt{2}\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span>,</span> נפעיל עליה את משפט לגראנז׳ בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\subset(0,1)\\)</span> ונקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(b)-f(a)=f'(c)(b-a)\\)</span>.</span> נחסום מלעיל את המונה של <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span> בעזרת <span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;1\\)</span> ואת המכנה מלרע בעזרת <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> ונקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&lt;\\frac{e}{2\\sqrt{2}}\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הגדרת הפונקציה והפעלת לגראנז׳.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1+e^x&gt;1&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (הרכבה של <span class=\"math math-inline\" dir=\"ltr\">\\(u\\mapsto\\sqrt{u}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^x\\)</span>,</span></span> משפטים 7.21, 7.31 ו-7.30) ורציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 7.9), ובפרט בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> נגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{e^x}{2\\sqrt{1+e^x}}.\\]</div>\n<p>לפי משפט לגראנז׳ (משפט 8.6) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt{1+e^b}-\\sqrt{1+e^a}=f(b)-f(a)=f'(c)(b-a)=\\frac{e^c}{2\\sqrt{1+e^c}}(b-a).\\]</div>\n<p><strong>שלב 2: חסימת הנגזרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span>.</span></span></strong> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;c&lt;b&lt;1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;c&lt;1\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> עולה ממש, ולכן:</p>\n<ul><li><strong>במונה</strong>: כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^c&lt;e^1=e\\)</span>.</span></li><li><strong>במכנה</strong>: כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^c&gt;e^0=1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^c&gt;2\\)</span>,</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\sqrt{1+e^c}&gt;2\\sqrt{2}&gt;0\\)</span>.</span></li></ul>\n<p><em>למה?</em> מותר לחסום את המונה מלמעלה ואת המכנה מלמטה <em>בנפרד</em> (שניהם חיוביים!) — מונה קטן יותר חלקי מכנה גדול יותר נותן שבר קטן יותר. לא צריך לחסום את כל הנגזרת דרך מציאת המונוטוניות שלה!</p>\n<p><strong>שלב 3: הסקת אי-השוויון.</strong> משתי ההערכות בשלב 2 ומכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b-a&gt;0\\)</span>,</span></span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(c)=\\frac{e^c}{2\\sqrt{1+e^c}}&lt;\\frac{e}{2\\sqrt{2}} \\implies \\sqrt{1+e^b}-\\sqrt{1+e^a}=f'(c)(b-a)&lt;\\frac{(b-a)e}{2\\sqrt{2}}.\\]</div>\n<p>לפיכך הטענה נכונה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;b&lt;1\\)</span>.</span></p>\n<p><strong>התשובה הנכונה: א</strong></p></div></div>","steps":["<p><strong>שלב 1: הגדרת הפונקציה והפעלת לגראנז׳.</strong> נגדיר <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{1+e^x}\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(1+e^x&gt;1&gt;0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (הרכבה של <span class=\"math math-inline\" dir=\"ltr\">\\(u\\mapsto\\sqrt{u}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^x\\)</span>,</span></span> משפטים 7.21, 7.31 ו-7.30) ורציפה בכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span> (משפט 7.9), ובפרט בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> נגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{e^x}{2\\sqrt{1+e^x}}.\\]</div>\n<p>לפי משפט לגראנז׳ (משפט 8.6) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(a,b)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\sqrt{1+e^b}-\\sqrt{1+e^a}=f(b)-f(a)=f'(c)(b-a)=\\frac{e^c}{2\\sqrt{1+e^c}}(b-a).\\]</div>","<p><strong>שלב 2: חסימת הנגזרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span>.</span></span></strong> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;c&lt;b&lt;1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;c&lt;1\\)</span>.</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(e^x\\)</span> עולה ממש, ולכן:</p>\n<ul><li><strong>במונה</strong>: כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;1\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^c&lt;e^1=e\\)</span>.</span></li><li><strong>במכנה</strong>: כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e^c&gt;e^0=1\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^c&gt;2\\)</span>,</span> ומכאן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\sqrt{1+e^c}&gt;2\\sqrt{2}&gt;0\\)</span>.</span></li></ul>\n<p><em>למה?</em> מותר לחסום את המונה מלמעלה ואת המכנה מלמטה <em>בנפרד</em> (שניהם חיוביים!) — מונה קטן יותר חלקי מכנה גדול יותר נותן שבר קטן יותר. לא צריך לחסום את כל הנגזרת דרך מציאת המונוטוניות שלה!</p>","<p><strong>שלב 3: הסקת אי-השוויון.</strong> משתי ההערכות בשלב 2 ומכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b-a&gt;0\\)</span>,</span></span> נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(c)=\\frac{e^c}{2\\sqrt{1+e^c}}&lt;\\frac{e}{2\\sqrt{2}} \\implies \\sqrt{1+e^b}-\\sqrt{1+e^a}=f'(c)(b-a)&lt;\\frac{(b-a)e}{2\\sqrt{2}}.\\]</div>\n<p>לפיכך הטענה נכונה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a&lt;b&lt;1\\)</span>.</span></p>\n<p><strong>התשובה הנכונה: א</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(e^c&gt;1\\)</span></span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(c&gt;0\\)</span> ואז לחסום בטעות <span class=\"math math-inline\" dir=\"ltr\">\\(1+e^c&gt;1\\)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+e^c&gt;2\\)</span>,</span> ולקבל <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e}{2}\\)</span> במקום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{e}{2\\sqrt{2}}\\)</span>.</span></li><li>להחליף את שתי הערכות המונה והמכנה (לשים <span class=\"math math-inline\" dir=\"ltr\">\\(e^1\\)</span> במכנה או <span class=\"math math-inline\" dir=\"ltr\">\\(e^0\\)</span> במונה) — שימו לב שזה נותן את השבר בכיוון הלא נכון או חסר תועלת.</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/29/q8\">2024א · מועד 81, שאלה 8</a></p>","mc":{"answer":"א"}},"9":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה גזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0,\\,f(1)=1\\)</span>.</span> אז: א. <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> ב. קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[0,1]\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=1\\)</span>.</span></span> ג. קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span> בה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יש מקסימום מקומי.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה גזירה שעולה בסך הכול מגובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> לגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> לא חייבת לעלות כל הדרך ולא חייבת להגיע לשיא באמצע, אבל השיפוע הממוצע שלה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> ולכן לפי משפט לגראנז׳ חייבת להיות נקודה שבה השיפוע הרגעי הוא בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה גזירה שעולה בסך הכול מגובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> לגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> לא חייבת לעלות כל הדרך ולא חייבת להגיע לשיא באמצע, אבל השיפוע הממוצע שלה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> ולכן לפי משפט לגראנז׳ חייבת להיות נקודה שבה השיפוע הרגעי הוא בדיוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p><strong>תמונה בראש</strong>: נסעתם קילומטר אחד בשעה אחת. ייתכן שבאמצע נסעתם קצת ברוורס (שולל מונוטוניות עולה), וייתכן שנסעתם ישר בקצב קבוע בלי אף פסגה בדרך (שולל מקסימום מקומי). אבל <em>אי-אפשר</em> שלא היה אפילו רגע אחד שבו מד המהירות הראה בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> קמ&quot;ש — כי המהירות הממוצעת הייתה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>:</p>\n<ul><li>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=2x^2-x\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=2-1=1\\)</span>,</span></span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\(f(\\frac{1}{4})=\\frac{1}{8}-\\frac{1}{4}=-\\frac{1}{8}&lt;0=f(0)\\)</span> — היא יורדת בהתחלה ולכן מפריכה את א!</li><li>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span>)</span> גזירה עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0, f(1)=1\\)</span>,</span> אבל היא עולה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> ולכן אין לה אף נקודת מקסימום מקומי בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> — מפריכה את ג!</li></ul>\n<p><strong>מקסימום מקומי</strong> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span></span> הוא נקודה שגבוהה או שווה לכל סביבתה הקרובה. <strong>מונוטונית עולה</strong> פירושה שככל שמתקדמים ימינה הערך לעולם אינו יורד.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x^2\\)</span> (אין לה מקסימום מקומי <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> — מפריכה את ג), באדום <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=2x^2-x\\)</span> (יורדת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בהתחלה — מפריכה את א), ובירוק מקווקו המיתר <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> בשיפוע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> הקווים הכתומים המקווקווים מראים שבשני המקרים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.5\\)</span></span> יש משיק מקביל בשיפוע בדיוק <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> (נכונות טענה ב).</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.15,&quot;ymin&quot;:-0.3,&quot;ymax&quot;:1.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=x^{2}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=2x^{2}-x&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;sec&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;tg&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0.25+(x-0.5)&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;tf&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=(x-0.5)&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1,1)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הפעלת משפט לגראנז׳","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הפעלת משפט לגראנז׳</p><div class=\"callout-body\"><p>מה הערך של המנה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(1)-f(0)}{1-0}\\)</span> לפי הנתון?</p></div></div>"},{"title":"רמז 2: שימו לב לתחום של $c$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימו לב לתחום של <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></p><div class=\"callout-body\"><p>משפט לגראנז׳ (8.6) מבטיח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span>,</span> ולכן בפרט גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[0,1]\\)</span>.</span></p></div></div>"},{"title":"רמז 3: הפריכו את א ואת ג","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: הפריכו את א ואת ג</p><div class=\"callout-body\"><p>חפשו פרבולה שיורדת מתחת לציר <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> ואז עולה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1,1)\\)</span>,</span></span> ופונקציה פשוטה שעולה כל הזמן בלי מקסימום מקומי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח את אפשרות ב ישירות בעזרת משפט לגראנז׳ על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> ולאחר מכן נפריך את אפשרות א ואת אפשרות ג באמצעות דוגמאות נגדיות פשוטות.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: בדיקת טענה ב (הנכונה).</strong> נתון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (משפט 7.9) וגזירה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(c)=\\frac{f(1)-f(0)}{1-0}=\\frac{1-0}{1}=1.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\subseteq[0,1]\\)</span>,</span></span> אותה נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> מקיימת גם <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=1\\)</span>.</span></span> לכן טענה ב נכונה.</p>\n<p><strong>שלב 2: הפרכת טענה א.</strong> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=2x^2-x\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> זו פונקציה פולינומית ולכן גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> ומתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=2-1=1\\)</span>.</span></span> עם זאת, <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac{1}{4}\\in(0,1)\\)</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f\\left(\\frac{1}{4}\\right)=2\\cdot\\frac{1}{16}-\\frac{1}{4}=-\\frac{1}{8}&lt;0=f(0).\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> וטענה א אינה נכונה.</p>\n<p><strong>שלב 3: הפרכת טענה ג.</strong> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> אולם <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=1\\ne 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span> אילו הייתה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> נקודת מקסימום מקומי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span>,</span></span> לפי משפט פרמה (משפט 8.4) היה חייב להתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>,</span> בסתירה לכך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=1\\)</span>.</span></span> לכן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אין מקסימום מקומי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> וטענה ג אינה נכונה.</p>\n<p><em>למה?</em> משפט לגראנז׳ מבטיח רק מה קורה לשיפוע בנקודה אחת מתאימה — הוא אינו אוסר על ירידות זמניות בדרך (הפרכת א), וקו ישר הוא פונקציה גזירה &quot;שגרתית&quot; שגדלה כל הזמן בלי אף פסגה פנימית (הפרכת ג).</p>\n<p><strong>התשובה הנכונה: ב</strong></p></div></div>","steps":["<p><strong>שלב 1: בדיקת טענה ב (הנכונה).</strong> נתון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (משפט 7.9) וגזירה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(c)=\\frac{f(1)-f(0)}{1-0}=\\frac{1-0}{1}=1.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\subseteq[0,1]\\)</span>,</span></span> אותה נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> מקיימת גם <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=1\\)</span>.</span></span> לכן טענה ב נכונה.</p>","<p><strong>שלב 2: הפרכת טענה א.</strong> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=2x^2-x\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> זו פונקציה פולינומית ולכן גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> ומתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=2-1=1\\)</span>.</span></span> עם זאת, <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=\\frac{1}{4}\\in(0,1)\\)</span></span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f\\left(\\frac{1}{4}\\right)=2\\cdot\\frac{1}{16}-\\frac{1}{4}=-\\frac{1}{8}&lt;0=f(0).\\]</div>\n<p>לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> וטענה א אינה נכונה.</p>","<p><strong>שלב 3: הפרכת טענה ג.</strong> ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f(1)=1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> גזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> אולם <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=1\\ne 0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>.</span> אילו הייתה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> נקודת מקסימום מקומי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span>,</span></span> לפי משפט פרמה (משפט 8.4) היה חייב להתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=0\\)</span>,</span> בסתירה לכך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=1\\)</span>.</span></span> לכן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אין מקסימום מקומי <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> וטענה ג אינה נכונה.</p>\n<p><em>למה?</em> משפט לגראנז׳ מבטיח רק מה קורה לשיפוע בנקודה אחת מתאימה — הוא אינו אוסר על ירידות זמניות בדרך (הפרכת א), וקו ישר הוא פונקציה גזירה &quot;שגרתית&quot; שגדלה כל הזמן בלי אף פסגה פנימית (הפרכת ג).</p>\n<p><strong>התשובה הנכונה: ב</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[0,1]\\)</span></span> בטענה ב שונה ממשפט לגראנז׳ שנותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,1)\\)</span>:</span> אם קיימת נקודה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span> היא בהכרח גם בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>!</span></li><li>להאמין שאם <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)&lt;f(1)\\)</span> אז הפונקציה חייבת לעלות כל הדרך (טענה א) — שכחו שהפונקציה יכולה לרדת תחילה ואז להשלים עלייה מהירה לקראת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/45/q5\">2026ג · מועד 83, שאלה 5</a></p>","mc":{"answer":"ב"}}};
